import { enemies } from "./content.mjs";
import { artPaths } from "./art-paths.mjs";
const enteredFloors = new WeakMap();
export function animateApexFloor(app, o, runId) {
  if (o.stratum !== 4 || o.mode !== "field") return;
  const field = app.querySelector(".field");
  if (!field) return;
  const key = `${runId}:${o.apex?.floor || 1}`;
  if (enteredFloors.get(app) === key) return;
  enteredFloors.set(app, key);
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  field.animate(
    [{ opacity: 0.3, transform: "scale(0.98)" }, { opacity: 1, transform: "scale(1)" }],
    { duration: 350, easing: "ease-out" },
  );
}
export function apexFieldSummary(o) {
  const f = o.field,
    remaining = f.archons.filter((a) => !f.defeatedArchons.includes(a.id));
  return `<div class="apex-deadline ${f.round >= 7 ? "urgent" : ""}"><strong>${f.round === 8 ? "Last movement · the Archons hunt next" : `Hunt after round 8 · ${8 - f.round} rounds after this one`}</strong><span>${f.defeatedArchons.length ? "Ascend is open at the center. The second victory forces ascent." : "Defeat either Archon, then reach Ascend. Defeating both forces ascent."}</span></div><div class="apex-roster">${f.archons.map((a) => `<span class="${remaining.includes(a) ? "" : "defeated"}" title="${enemies[a.id].name} · ${a.x + 1}, ${a.y + 1} · ${f.defeatedArchons.includes(a.id) ? "Defeated" : "Stationary until the hunt"}"><img src="${artPaths["enemy-" + a.id]}" alt="">${enemies[a.id].name}${f.defeatedArchons.includes(a.id) ? " ✓" : ""}</span>`).join("")}</div>`;
}
export function apexMarks(f, x, y) {
  const a = f.archons?.find((a) => a.x === x && a.y === y);
  return a
    ? `<span class="apex-seal ${f.defeatedArchons.includes(a.id) ? "fallen" : ""}" title="${enemies[a.id].name} appears here on round 4"><img src="${artPaths["enemy-" + a.id]}" alt="${enemies[a.id].name}"><span>◇</span></span>`
    : "";
}
export function apexIntroMarkup(actions, button) {
  return `<section class="scene apex-intro"><div class="scene-art"></div><div class="scene-copy"><div class="eyebrow">Stratum four</div><h2>The Apex</h2><div class="rule"></div><p>Above the crystal ridges, rivers of fire carve a path toward something that has been waiting for you.</p><p>Three floors. Two familiar Archons on each. Defeat one and take the central stairs, or defeat both to ascend immediately.</p><p>The Archons arrive on round 4. After round 8’s movement, every survivor hunts you together.</p><div class="choices">${actions.map((a) => button(a, "primary")).join("")}</div></div></section>`;
}
export function apexSummitMarkup(o, actions, button) {
  return `<section class="scene apex-summit"><div class="scene-art"><img class="apex-beast" src="assets/enemy-apex.png" alt="The Apex Predator"></div><div class="scene-copy"><div class="eyebrow">The Apex · Floor 4</div><h2>The Apex Predator</h2><div class="rule"></div><p>Rock fractures beneath its weight. At the edges of its hide, darkness refuses to hold a shape.</p><p>No pursuit. No further provisions. The beast waits.</p><div class="apex-summit-room" aria-label="Five by five summit room; you enter at the center">${Array.from({ length: 25 }, (_, i) => `<span class="${i === 12 ? "summit-center" : ""}">${i === 12 ? "✧" : ""}</span>`).join("")}</div><div class="choices">${actions
    .filter((a) => a.type === "fightApex")
    .map((a) => button(a, "primary"))
    .join("")}</div></div></section>`;
}

apex.mjs:
import { enemies, items } from "./content.mjs";

export const APEX_SIZES = [11, 9, 7, 5];
export const apexActive = (s) => s.stratum === 4 && !!s.apex;
export const fieldSize = (f) => f.size || 11;
export function apexMovement(d, e) {
  if (!e.apexMap || d.tier !== "Mote") return d;
  return {
    ...d,
    movement: ["Hunter", "Stalker"].includes(d.movement)
      ? d.movement
      : "Wanderer",
    speed: ["Hunter", "Stalker"].includes(d.movement) ? d.speed || 2 : 1,
  };
}
export function apexStats(d, e) {
  if (!e.apexMap || d.id === "apex" || d.apexNative)
    return { hp: d.hp, damageBonus: 0 };
  const floor = e.apexFloor;
  if (d.tier === "Archon")
    return {
      hp: d.id === "mindHive" ? d.hp : Math.ceil(d.hp * (floor === 3 ? 1.1 : floor === 1 ? 1.485 : 1.32)),
      damageBonus: floor === 3 ? 0 : floor === 1 ? 3 : 2,
    };
  return {
    hp: Math.ceil(d.hp * [0, 1.76, 1.485, 1.265][floor]),
    damageBonus: [0, 4, 3, 2][floor],
  };
}
export function enterApexFloor(g, floor = 1) {
  const s = g.s;
  s.apex ||= { floor: 0, required: [], defeated: [], visits: [] };
  if (s.apex.floor)
    s.apex.visits.push({
      floor: s.apex.floor,
      round: s.field.round,
      abandoned: s.field.entities
        .filter((e) => e.apexMap && e.enemy)
        .map((e) => e.uid),
      hp: s.hp,
    });
  s.apex.floor = floor;
  const size = APEX_SIZES[floor - 1],
    c = Math.floor(size / 2);
  s.field = {
    size,
    apexFloor: floor,
    round: 0,
    spawned: 0,
    spawnWidth: 2,
    queue: [],
    entities: [],
    x: c,
    y: c,
    moves: 0,
    stage: "player",
    archons: [],
    defeatedArchons: [],
  };
  if (floor < 4)
    s.field.archons = g
      .shuffle(
        Object.values(enemies)
          .filter((e) => e.tier === "Archon" && (e.stratum || 1) === floor)
          .map((e) => e.id),
      )
      .slice(0, 2)
      .map((id, i) => ({ id, x: c + (i ? 2 : -2), y: c - 2 }));
  s.archon = floor === 4 ? "apex" : s.field.archons[0].id;
  s.enemyDecks = {};
  s.mode = "field";
  delete s.battle;
  delete s.reward;
  delete s.checkpoint;
  delete s.itemSource;
  g.log(
    `The Apex · Floor ${floor}. ${floor === 4 ? "The Apex Predator waits." : "The Archons hunt after round 8. Defeating both forces ascent."}`,
  );
  g.present("ascent", { floor, name: "The Apex · Floor " + floor });
  if (floor < 4) g.beginRound();
}
export function apexBatch(g) {
  const f = g.s.field;
  if (f.apexFloor === 4) return;
  while (f.queue.length < Math.min(8, 16 - f.spawned)) {
    const number = f.spawned + f.queue.length + 1;
    // 60% encounters (4:1 Mote:Eidolon), 25% Gold, 15% Item.
    const roll = () => {
      const n = g.rand();
      return n < 0.48
        ? "Mote"
        : n < 0.6
          ? "Eidolon"
          : n < 0.85
            ? "Gold"
            : "Item";
    };
    f.queue.push(
      number === 7 || number === 8
        ? "Archon"
        : f.apexFloor === 3 && number === 1
          ? "Tavern"
          : roll(),
    );
  }
}
export function apexRound(g) {
  const s = g.s,
    f = s.field;
  if (f.apexFloor === 4) return;
  f.round++;
  f.moves = g.bonuses().movement;
  f.stage = "player";
  s.mode = "field";
  for (const e of f.entities) if (e.type === "Gold") e.value -= 5;
  f.entities = f.entities.filter((e) => e.type !== "Gold" || e.value > 0);
  if (f.round > 8) throw Error("Apex cannot generate a ninth round");
  apexBatch(g);
  const c = Math.floor(f.size / 2);
  // Keep the stairs, two diagonal approaches and marked Archon spaces free of random spawns.
  const reserved = (x, y) =>
    (x === c && y === c) ||
    (y === c - 1 && Math.abs(x - c) === 1) ||
    f.archons.some((a) => a.x === x && a.y === y);
  const spaces = [];
  for (let y = 0; y < f.size; y++)
    for (let x = 0; x < f.size; x++)
      if (!reserved(x, y) && !(x === f.x && y === f.y)) spaces.push({ x, y });
  for (const type of f.queue.splice(0, 2)) {
    f.spawned++;
    const mark = type === "Archon" ? f.archons[f.spawned - 7] : null;
    const pos = mark || g.pick(spaces);
    const e = {
      uid: g.uid(),
      type,
      x: pos.x,
      y: pos.y,
      restless: 0,
      born: f.round,
      apexMap: true,
      apexFloor: f.apexFloor,
    };
    if (mark) e.enemy = mark.id;
    else if (["Mote", "Eidolon"].includes(type)) {
      const pool = Object.values(enemies)
        .filter(
          (d) =>
            d.tier === type &&
            ((d.stratum || 1) === f.apexFloor || d.apexNative) &&
            !d.tutorialOnly &&
            !d.summonOnly,
        )
        .map((d) => d.id);
      if (!s.enemyDecks[type]?.length) s.enemyDecks[type] = g.shuffle(pool);
      e.enemy = s.enemyDecks[type].pop();
    }
    if (e.enemy) {
      e.count = type === "Archon" ? 1 : g.groupSize(e.enemy, f.round + 4);
      s.apex.required.push({
        uid: e.uid,
        enemy: e.enemy,
        count: e.count,
        floor: f.apexFloor,
      });
    }
    if (type === "Gold") e.value = 30 + Math.floor(g.rand() * 8) * 10;
    f.entities.push(e);
    g.log(
      `${e.enemy ? enemies[e.enemy].name : type} appears at ${e.x + 1}, ${e.y + 1}.`,
    );
  }
  if (f.round % 4 === 0)
    for (const e of f.entities)
      if (e.enemy && e.type !== "Archon") e.restless++;
  apexBatch(g);
  g.resolveTile();
}
export function apexVictory(g, original) {
  const s = g.s,
    f = s.field;
  for (const e of original)
    if (e.apexMap && !s.apex.defeated.includes(e.entityUid))
      s.apex.defeated.push(e.entityUid);
  const bosses = original.filter((e) => e.tier === "Archon");
  for (const e of bosses)
    if (e.id !== "apex" && !f.defeatedArchons.includes(e.id))
      f.defeatedArchons.push(e.id);
  if (
    bosses.length &&
    f.apexFloor < 4 &&
    !f.entities.some((e) => e.type === "Ascend")
  ) {
    const c = Math.floor(f.size / 2);
    f.entities.push({ uid: g.uid(), type: "Ascend", x: c, y: c });
    g.log(
      "Ascend appears at the center. Defeat the second Archon to ascend automatically.",
    );
  }
  const offer = () => (g.rand() < 0.35 ? g.bossOffer() : g.rareOffer(3, true));
  const offers = bosses.map(offer);
  const goodItems = [
    "gold",
    "mirrorArmor",
    "focusGem",
    "channelGem",
    "holyArmor",
    "sapphire",
    "insightGem",
  ];
  return {
    cards:
      offers.shift() || g.offer(original.some((e) => e.tier === "Eidolon")),
    boss: !!bosses.length,
    apexReward: true,
    extraOffers: offers,
    gem: false,
    setting:
      bosses.length && g.rand() < 0.5
        ? g.pick(goodItems.filter((id) => items[id]))
        : false,
    apexAscend: f.defeatedArchons.length === 2,
    apexFinal: bosses.some((e) => e.id === "apex"),
  };
}
export function apexComplete(s) {
  return (
    !!s.apex &&
    [1, 2, 3].every(
      (floor) =>
        s.apex.required.filter(
          (e) => e.floor === floor && enemies[e.enemy]?.tier === "Archon",
        ).length === 2,
    ) &&
    s.apex.required.every((e) => s.apex.defeated.includes(e.uid))
  );
}

archive-profile.mjs:
import { cards, enemies, items, events } from "./content.mjs";

export const achievements = [
  { id: "defeat-mindHive", name: "Defeat the Mind Hive", enemy: "mindHive" },
  { id: "defeat-cnidarian", name: "Defeat the Cnidarian", enemy: "cnidarian" },
  {
    id: "defeat-refractionCannon",
    name: "Defeat the Refraction Cannon",
    enemy: "refractionCannon",
  },
  { id: "defeat-blackBile", name: "Defeat The Black Bile", enemy: "blackBile" },
  { id: "defeat-bombadier", name: "Defeat King Bombadier", enemy: "bombadier" },
  { id: "defeat-trickster", name: "Defeat The Trickster", enemy: "trickster" },
  {
    id: "defeat-seamstress",
    name: "Defeat the Seamstress of Absence",
    enemy: "seamstress",
  },
  { id: "defeat-censer", name: "Defeat the Censer Engine", enemy: "censer" },
  {
    id: "defeat-borrowedChoir",
    name: "Defeat the Choir of Borrowed Hands",
    enemy: "borrowedChoir",
  },
  { id: "defeat-hart", name: "Defeat the Cinder Hart", enemy: "hart" },
  {
    id: "defeat-colossus",
    name: "Defeat the Void-Colossus",
    enemy: "colossus",
  },
  { id: "defeat-choir", name: "Defeat the Glass Choir", enemy: "choir" },
  { id: "defeat-apex", name: "Defeat the Apex Predator", enemy: "apex" },
  { id: "i-stand-alone", name: "I Stand Alone" },
  { id: "without-menders", name: "Without the Menders" },
  { id: "calm-apex", name: "Calm the Apex Predator" },
  { id: "calm-astrata", name: "Calm Astrata" },
  {
    id: "traveler-kindness",
    name: "A Little Kindness",
    hiddenStratumPrerequisite: true,
  },
];
export function emptyCollection() {
  return { schema: 1, cards: {}, enemies: {}, equipment: {}, achievements: {} };
}
export function discover(collection, state, at = new Date().toISOString()) {
  if (!state) return collection;
  for (const key of ["cards", "enemies", "equipment", "achievements"])
    collection[key] ||= {};
  collection.highestStratum = Math.max(collection.highestStratum || 1, state.stratum || 1);
  const seen = (kind, id) => {
    const catalog = { cards, enemies, equipment: items }[kind];
    if (catalog[id]) collection[kind][id] ||= { firstSeenAt: at };
  };
  const offer = (id) => {
    if (typeof id !== "string") return;
    if (id.startsWith("card:")) seen("cards", id.slice(5));
    else seen("equipment", id);
  };
  for (const c of state.deck || []) seen("cards", c.id);
  for (const i of state.inventory || []) seen("equipment", i.id);
  for (const e of state.field?.entities || []) {
    seen("enemies", e.enemy);
    if (items[e.item]?.consumable) seen("equipment", e.item);
  }
  for (const e of [
    ...(state.battle?.enemies || []),
    ...(state.battle?.ideons || []),
  ])
    seen("enemies", e.id);
  if (state.mode === "reward")
    for (const id of state.reward?.cards || []) seen("cards", id);
  if (state.mode === "item") for (const id of state.itemOffer || []) offer(id);
  if (state.mode === "tavern")
    for (const id of state.shop?.stock || []) offer(id);
  if (state.mode === "event") {
    const event =
      typeof state.event === "string"
        ? events.find((e) => e.id === state.event)
        : state.event;
    for (const choice of event?.choices || []) {
      // These authored choices show the named reward in the visible choice text.
      for (const id of [choice.card, choice.hex]) if (id) seen("cards", id);
      if (choice.item) seen("equipment", choice.item);
    }
  }
  // Legacy summaries can establish acquired content and encountered enemies, not unseen offers.
  for (const [field, kind, catalog] of [
    ["cardsGained", "cards", cards],
    ["itemsGained", "equipment", items],
  ]) {
    for (const name of state.stats?.[field] || []) {
      const id = Object.keys(catalog).find((id) => catalog[id].name === name);
      if (id) seen(kind, id);
    }
  }
  for (const encounter of state.stats?.encounters || []) {
    for (const name of encounter.enemies || []) {
      const aliases = {
        "The Cinder Heart": "hart",
        "Cinder Heart": "hart",
        "Cinder Hart": "hart",
        "Void Colossus": "colossus",
        "Glass Choir": "choir",
      };
      const id =
        aliases[name] ||
        Object.keys(enemies).find(
          (id) => enemies[id].name === name.replace(/ \d+$/, ""),
        );
      if (!id) continue;
      seen("enemies", id);
      const achievement = achievements.find((a) => a.enemy === id);
      if (achievement && encounter.outcome === "victory" && !state.tutorial)
        collection.achievements[achievement.id] ||= { earnedAt: at };
    }
  }
  if (
    !state.tutorial &&
    [1, 2, 3].every((afterStratum) =>
      state.stats?.travelerDonations?.some(
        (d) => d.afterStratum === afterStratum && d.gold > 0,
      ),
    )
  )
    collection.achievements["traveler-kindness"] ||= { earnedAt: at };
  if (!state.tutorial && state.outcome === "win" && state.stratum === 4) {
    if (state.stats?.iStandAlone) collection.achievements["i-stand-alone"] ||= {earnedAt:at};
    if (state.stats?.withoutMendersCompleted) collection.achievements["without-menders"] ||= {earnedAt:at};
  }
  return collection;
}

archives-ui.mjs:
import { pressureSignature, pressureTell } from "./difficulty.mjs";
import { cards, enemies, items, cardText } from "./content.mjs";
import { achievements } from "./archive-profile.mjs";

const sections = [
  ["history", "Run History", "Journeys remembered", "Ⅰ"],
  ["cards", "Cards", "Leaves of the Grimoire", "Ⅱ"],
  ["enemies", "Enemies", "Faces of the Strata", "Ⅲ"],
  ["equipment", "Equipment", "Treasures along the path", "Ⅳ"],
  ["achievements", "Achievements", "Deeds and mysteries", "Ⅴ"],
];
export function showArchives(ctx, section = "hub") {
  const { app, data, esc, img, text, dialog } = ctx,
    collection = data.collections;
  let query = "",
    visibility = "all";
  const heading = sections.find(([id]) => id === section)?.[1] || "Archives";
  app.innerHTML = `<section class="archives"><header class="archives-heading"><div><div class="eyebrow">ASTRATA · THE ARCHIVES</div><h1>${heading}</h1></div><button data-archive-back>${section === "hub" ? "Return to start" : "All Archives"} ↗</button></header>${section === "hub" ? "" : `<nav class="archive-tabs" aria-label="Archives sections">${sections.map(([id, title]) => `<button data-archive-nav="${id}" aria-current="${section === id ? "page" : "false"}">${title}</button>`).join("")}</nav>`}<div class="archive-body"></div></section>`;
  app.querySelector("[data-archive-back]").onclick = () =>
    section === "hub" ? ctx.home() : showArchives(ctx);
  app
    .querySelectorAll("[data-archive-nav]")
    .forEach(
      (el) => (el.onclick = () => showArchives(ctx, el.dataset.archiveNav)),
    );
  app.querySelector("[data-archive-back]").focus();
  const body = app.querySelector(".archive-body");
  if (section === "hub") {
    body.innerHTML = `<p class="archive-intro">What you have found. What remains unknown.</p><div class="archive-volumes">${sections.map(([id, title, sub, numeral]) => `<button class="archive-volume" data-volume="${id}"><span class="archive-numeral">${numeral}</span><h2>${title}</h2><span>${sub}</span><b aria-hidden="true">↗</b></button>`).join("")}</div>`;
    body
      .querySelectorAll("[data-volume]")
      .forEach(
        (el) => (el.onclick = () => showArchives(ctx, el.dataset.volume)),
      );
    return;
  }
  if (section === "history") {
    const recent = (data.history || []).slice(-20).reverse();
    body.innerHTML = `<p class="muted">The most recent 20 journeys</p><div class="archive-history">${recent.map((h, i) => `<button data-run="${i}"><span class="archive-run-number">${String(i + 1).padStart(2, "0")}</span><span><b>${h.tutorial ? "The First Clearing" : "The Whispering Weald"}</b><small>${esc(h.outcome)} · Round ${h.field?.round ?? "—"} · Seed ${esc(h.seed)}</small></span><span class="muted">v${esc(h.packageVersion || "unrecorded")} ↗</span></button>`).join("") || "<p>No journeys recorded yet.</p>"}</div>`;
    body
      .querySelectorAll("[data-run]")
      .forEach(
        (el) =>
          (el.onclick = () =>
            dialog(ctx.resultMarkup(recent[Number(el.dataset.run)]))),
      );
    return;
  }
  if (section === "achievements") {
    body.innerHTML = `<div class="archive-achievements">${achievements
      .map((a) => {
        const earned = collection.achievements?.[a.id];
        return `<article class="archive-achievement ${earned ? "earned" : ""}"><span class="achievement-seal" aria-hidden="true">${earned ? "✦" : "◇"}</span><div><h2>${esc(a.name)}</h2><span class="${earned ? "gold" : "muted"}">${earned ? "Achieved" : "Not yet achieved"}</span></div></article>`;
      })
      .join("")}</div>`;
    return;
  }
  const catalog = { cards, enemies, equipment: items }[section];
  if (!catalog) return;
  const discovered = collection[section] || {},
    entries = Object.entries(catalog);
  body.innerHTML = `<div class="archive-filters"><span>${entries.filter(([id]) => discovered[id]).length} / ${entries.length} discovered</span><label>Find <input type="search" aria-label="Search discovered entries" placeholder="Search discoveries"></label><label>Show <select aria-label="Collection visibility"><option value="all">All entries</option><option value="seen">Discovered</option><option value="unseen">Undiscovered</option></select></label></div><div class="archive-gallery"></div>`;
  const gallery = body.querySelector(".archive-gallery");
  function paint() {
    const filtered = entries.filter(
      ([id, d]) =>
        (visibility !== "seen" || discovered[id]) &&
        (visibility !== "unseen" || !discovered[id]) &&
        (!query || (discovered[id] && d.name.toLowerCase().includes(query))),
    );
    gallery.innerHTML =
      filtered
        .map(([id, d]) =>
          discovered[id]
            ? `<button class="archive-entry" data-entry="${id}">${img({ cards: "card-", enemies: "enemy-", equipment: "item-" }[section] + id)}<span class="archive-entry-copy"><b>${esc(d.name)}</b><small>${esc(d.element || d.slot || d.type)}${d.tier ? " · " + esc(d.tier) : ""}</small></span></button>`
            : `<div class="archive-entry undiscovered" aria-label="Undiscovered ${section === "equipment" ? "equipment" : section === "enemies" ? "enemy" : "card"}"><span class="unknown-sigil">?</span><span class="archive-entry-copy"><b>Undiscovered</b></span></div>`,
        )
        .join("") || '<p class="muted">No matching discoveries.</p>';
    gallery
      .querySelectorAll("[data-entry]")
      .forEach((el) => (el.onclick = () => details(el.dataset.entry)));
  }
  function details(id) {
    if (!discovered[id]) return;
    const d = catalog[id],
      prefix = { cards: "card-", enemies: "enemy-", equipment: "item-" }[
        section
      ];
    const specifics =
      section === "cards"
        ? `<p class="gold">${esc(d.element)} · ${esc(d.type)} · ${esc(d.rarity)}</p><p>Focus ${d.unplaceable ? "Automatic" : d.focus} · Activation allowance ${d.limit < 0 ? "∞" : d.limit} · Channel ${d.channel ?? 1}${d.hp ? " · Initial HP " + d.hp : ""}${d.charge ? " · Charge " + d.charge : ""} · Recall ${d.recall == null ? "Unavailable" : d.recall}</p><p>${text(cardText(d, collection.highestStratum || 1))}</p>`
        : section === "enemies"
          ? `<p class="gold">${esc(d.tier)} · ${esc(d.element)} · ${d.hp} base HP</p><p>${esc(d.schedule || d.movement)}</p><p>${text(pressureSignature(d.signature,d))}</p><h3>Move cycle</h3><ol>${d.rotation.map((t) => `<li>${text(ctx.tellText(pressureTell(t,d)))}</li>`).join("")}</ol>${d.onDeath ? `<h3>On death</h3><p>${text(ctx.tellText(pressureTell(d.onDeath,d)))}</p>` : ""}<p class="muted">${text(d.counter)}</p>`
          : `<p class="gold">${esc(d.slot)}</p><p>${text(d.text)}</p>`;
    dialog(
      `<div class="archive-detail">${img(prefix + id, "full-art")}<div><div class="eyebrow">${heading} · Discovered</div><h2>${esc(d.name)}</h2>${specifics}</div></div>`,
    );
  }
  body.querySelector("input").oninput = (e) => {
    query = e.target.value.trim().toLowerCase();
    paint();
  };
  body.querySelector("select").onchange = (e) => {
    visibility = e.target.value;
    paint();
  };
  paint();
}

