import { statHelp, statAttribute } from "./card-upgrade-ui.mjs";
import { cards, glossary } from "./content.mjs";
import { attackElements, attackPreview } from "./combat-preview.mjs";
import { cardPower } from "./engine.mjs";
import { corruptionPower, cardFrozen, cardSevered, insanityCover } from "./corruptions.mjs";
export function damageMarkup(b, c, slot) {
  return `Deal <b class="damage-value" data-tooltip="${statAttribute(statHelp(b, c, slot))}">${cardPower(b, c, slot)}${attackElements(b, c, slot).length > 1 ? " ×" + attackElements(b, c, slot).length : ""}</b>`;
}
export function targetPreview(ctx, source, slot, actionFor) {
  const number = source?.querySelector(".damage-value");
  const normal = number?.textContent;
  const normalHelp = number?.dataset.tooltip;
  let target = null;
  function clear() {
    if (number) {
      number.textContent = normal;
      number.classList.remove("damage-up", "damage-down");
      if (normalHelp) number.dataset.tooltip = normalHelp;
      else number.removeAttribute("data-tooltip");
    }
    ctx.app
      .querySelectorAll(".target-damage-preview")
      .forEach((el) => el.remove());
    target = null;
  }
  function show(choice) {
    const action = actionFor(choice);
    if (!action || !number) {
      clear();
      return;
    }
    if (target === choice) return;
    clear();
    const b = ctx.o.battle,
      c = b.grid[slot].at(-1);
    const enemy = [...b.enemies, ...(b.ideons || [])].find(
      (e) => e.uid === action.target,
    );
    if (!enemy) return;
    const v = attackPreview(b, c, slot, enemy, action.element, action);
    if (!v) return;
    target = choice;
    const tone = v.delta > 0 ? "damage-up" : v.delta < 0 ? "damage-down" : "";
    const label = `${v.damage}${v.delta ? ` (${v.delta > 0 ? "+" : ""}${v.delta})` : ""}`;
    const help = `${v.base} base → ${v.damage} ${v.elements.join("/")} card damage against ${enemy.name}.${corruptionPower(b, slot, 4) < 4 ? " Nausea has already halved the base damage before the elemental matchup." : ""} ${v.blocked} absorbed by Guard; ${v.hpLoss} HP lost.${v.negated ? " Flicker negates this activation." : ""} Equipment hits, covered-card effects and status damage resolve separately.`;
    number.textContent = label;
    if (tone) number.classList.add(tone);
    number.dataset.tooltip = help;
    const badge = document.createElement("div");
    badge.className = "target-damage-preview " + tone;
    badge.dataset.tooltip = help;
    badge.textContent = `${label} damage · ${v.hpLoss} HP`;
    choice.append(badge);
  }
  function leave(e) {
    if (target?.contains(e.target) && !target.contains(e.relatedTarget))
      clear();
  }
  return { show, clear, leave };
}
const icons = {
  Taunt:
    '<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4M12 19v4M1 12h4M19 12h4"/>',
  Lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  Freeze: '<path d="M12 2v20M3 7l18 10M3 17L21 7M8 4l4 4 4-4M8 20l4-4 4 4"/>',
  Sever:
    '<path d="M9 4H6a4 4 0 0 0-4 4v2a4 4 0 0 0 4 4h3M15 10h3a4 4 0 0 1 4 4v2a4 4 0 0 1-4 4h-3M14 3L9 12h6l-5 9"/>',
  Burn: '<path d="M13 2c2 7-3 6-1 11 2-1 3-3 3-5 5 4 6 13-3 14C3 21 2 15 6 9c0 4 2 4 3 3-2-4 2-6 4-10Z"/>',
  Poison:
    '<path d="M9 2h6M10 2v7L4 19q-1 3 3 3h10q4 0 3-3L14 9V2M7 15h10M10 18h1M14 19h1"/>',
  Corrode:
    '<path d="M8 2s-5 6-5 9a5 5 0 0 0 10 0c0-3-5-9-5-9ZM18 8s-3 4-3 6a3 3 0 0 0 6 0c0-2-3-6-3-6ZM2 22h5l2-3 3 3h10"/>',
  Depleted: '<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6ZM3 21 21 3"/>',
  Spent: '<circle cx="12" cy="12" r="9"/><path d="M6 12h12"/>',
  Used: '<path d="M5 2h14M5 22h14M7 2v5l10 10v5M17 2v5L7 17v5"/>',
};
export function statusBadges(ctx, c, i) {
  const d = cards[c.id],
    b = ctx.o.battle,
    states = [];
  if (c.taunt)
    states.push([
      "Taunt",
      "Taunt",
      glossary.Taunt +
        (c.tauntUntil != null ? " Ends after this enemy phase." : ""),
    ]);
  if (c.lock) states.push(["Lock", "Locked", glossary.Lock]);
  const insanity = insanityCover(b, i);
  if (cardFrozen(b, c, i)) states.push(["Freeze", "Frozen", insanity ? "Insanity freezes this card while it covers this space. Repair from adjacent Machine Elves or Recall the card to uncover the HP-damaging space." : glossary.Freeze]);
  if (cardSevered(b, c, i)) states.push(["Sever", "Severed", insanity ? "Insanity: this card gives and receives no adjacency or pattern connections while covering this space." : glossary.Sever]);
  for (const name of ["Burn", "Poison", "Corrode"]) {
    const value = c.status?.[name.toLowerCase()] || 0;
    if (value) states.push([name, `${name} ${value}`, glossary[name], value]);
  }
  if (c.zeroWard)
    states.push([
      "Depleted",
      "Depleted",
      "fully depleted wards cannot activate.",
    ]);
  else if (d.limit > 0 && !ctx.game.allowance(c, i))
    states.push(["Spent", "Spent", glossary.Spent]);
  else if (!d.blink && c.lastActivatedTurn === b.turn)
    states.push([
      "Used",
      "Used this turn",
      "This card has already activated this turn. It may activate again next player turn if allowance remains.",
    ]);
  return states.length
    ? `<div class="card-statuses">${states
        .map(
          ([key, label, help, value]) =>
            `<span class="card-status status-${key.toLowerCase()}" data-card-status="${key}" role="img" aria-label="${label}" data-tooltip="${ctx.esc(label + ": " + help)}"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[key]}</svg>${value ? `<b>${value}</b>` : ""}</span>`,
        )
        .join("")}</div>`
    : "";
}
export function upgradeHelp(d) {
  const u = d.upgrade;
  if (!u) return "";
  const f = d.effects,
    n = u.bonus || 0,
    gains = [];
  if (u.effects?.damage)
    gains.push(`Add ${u.effects.damage} direct ${d.element} damage`);
  if (f.damage) gains.push(`Damage ${f.damage} → ${f.damage + n}`);
  if (d.hp) gains.push(`Initial HP ${d.hp} → ${d.hp + n}`);
  if (f.shield) gains.push(`Shield ${f.shield} → ${f.shield + n}`);
  if (f.heal) gains.push(`Heal ${f.heal} → ${f.heal + n}`);
  for (const [key, label] of [
    ["burn", "Burn"],
    ["poison", "Poison"],
    ["corrode", "Corrode"],
    ["ward", "Ward gain"],
  ])
    if (f[key]) gains.push(`${label} ${f[key]} → ${f[key] + n}`);
  return [u.text, ...gains].join(" · ");
}

export function gridTelegraphs(ctx) {
  const warnings = new Map();
  const icon =
    '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 22 21H2Z"/><path d="M12 9v5m0 3v1"/></svg>';
  for (const t of ctx.o.battle.telegraphs || []) {
    const rule =
      t.kind === "row"
        ? "Fullest row; ties choose the topmost row."
        : t.kind === "column"
          ? "Fullest column; ties choose the leftmost column."
          : t.target === "valuable"
            ? "Two most dangerous complete stacks: total damage/defense potential, then printed Focus, remaining activations and reading order. Both targets are chosen before destruction."
            : "Tallest complete stack; ties choose the first occupied space in reading order.";
    const extra = t.damagePerEmpty
      ? ` Then ${t.damage} Arcane damage: ${t.emptySpaces} spaces empty before destruction × ${t.damagePerEmpty}. Destroyed cards cannot defend.`
      : t.burn
        ? ` Then inflicts Burn ${t.burn} on the player.`
        : "";
    const help = `${t.enemy} — ${t.name}: destroys ${t.cards} card${t.cards === 1 ? "" : "s"} on the upcoming enemy turn.${extra} ${rule} Covered cards count. Live preview: changes with your placements, Recalls and remaining activations.`;
    const enemy = ctx.app.querySelector(`[data-enemy-uid="${t.source}"] .info`);
    const label = document.createElement("div");
    label.className = "grid-threat-label";
    label.dataset.tooltip = help;
    label.innerHTML =
      icon +
      `<span>${t.cards ? `${t.cards} card${t.cards === 1 ? "" : "s"} threatened` : "No cards threatened"} · next enemy turn</span>`;
    enemy?.append(label);
    for (const i of t.spaces) {
      if (!warnings.has(i)) warnings.set(i, []);
      warnings
        .get(i)
        .push({ help, occupied: t.targets.includes(i), source: t.source });
    }
  }
  for (const [i, threats] of warnings) {
    const slot = ctx.app.querySelector(`[data-slot="${i}"]`);
    if (!slot) continue;
    slot.classList.add("grid-threat");
    slot.dataset.threatSources = threats.map((t) => t.source).join(",");
    const help = threats.map((t) => t.help).join(" ");
    slot.setAttribute(
      "aria-label",
      slot.getAttribute("aria-label") + ". Warning: " + help,
    );
    const outline = document.createElement("span");
    outline.className = "grid-threat-outline";
    outline.setAttribute("aria-hidden", "true");
    slot.append(outline);
    if (threats.some((t) => t.occupied)) {
      const badge = document.createElement("span");
      badge.className = "grid-threat-badge";
      badge.dataset.tooltip = help;
      badge.setAttribute("role", "img");
      badge.setAttribute("aria-label", "Destruction warning");
      badge.innerHTML = icon;
      slot.append(badge);
    }
  }
}

battle-layout.mjs:
import { items, MIND_COLUMNS, MIND_ROWS } from "./content.mjs";
let toolsOpen = false;
export function arrangeBattle(ctx) {
  const { app, o, actions } = ctx;
  const old = app.querySelector(".layout"),
    mind = app.querySelector(".mind");
  if (!old || !mind) return;
  app.classList.add("battle-scene");
  mind.style.setProperty("--mind-columns", MIND_COLUMNS);
  mind.style.setProperty("--mind-rows", MIND_ROWS);
  const layout = document.createElement("section");
  layout.className = "battle-layout";
  const command = document.createElement("div");
  command.className = "battle-command";
  command.append(
    app.querySelector(".phasebar"),
    app.querySelector(".resources"),
  );
  const arena = document.createElement("div");
  arena.className = "battle-arena";
  const player = app.querySelector(".battle-player");
  const enemies = app.querySelector(".enemy-line");
  const enemyArea = document.createElement("section");
  enemyArea.className = "battle-foes";
  const heading = document.createElement("div");
  heading.className = "eyebrow";
  heading.textContent = `Enemies · ${o.battle.enemies.length}`;
  enemies.classList.toggle("solo-enemy", o.battle.enemies.length === 1);
  enemies.classList.toggle("many-enemies", o.battle.enemies.length > 3);
  enemies.classList.toggle("crowded-enemies", o.battle.enemies.length > 6);
  enemyArea.append(heading, enemies);
  arena.append(player, mind, enemyArea);
  const dock = document.createElement("section");
  dock.className = "battle-dock";
  const incoming = old.querySelector(".incoming-attack");
  const hand = old.querySelector(".revealed-hand");
  if (incoming) dock.append(incoming);
  else if (hand) dock.append(hand);
  else dock.innerHTML = '<div class="eyebrow">Revealed cards</div>';
  const footer = document.createElement("footer");
  footer.className = "battle-footer";
  const piles = old.querySelector('[data-ui="piles"]');
  if (piles) footer.append(piles);
  const turn = document.createElement("span");
  turn.className = "battle-turn";
  turn.textContent = `Turn ${o.battle.turn}`;
  footer.append(turn);
  const tools = document.createElement("details");
  tools.className = "battle-tools";
  tools.open = toolsOpen;
  tools.ontoggle = () => {
    if (tools.isConnected) toolsOpen = tools.open;
  };
  tools.innerHTML = "<summary>Battle tools</summary>";
  const sidebar = old.querySelector(".sidebar");
  if (sidebar) tools.append(sidebar);
  footer.append(tools);
  layout.append(command, arena, dock, footer);
  old.replaceWith(layout);
  const activeEnemy = enemies.querySelector(
    `[data-enemy-uid="${o.battle.reaction?.source}"]`,
  );
  if (activeEnemy)
    activeEnemy.scrollIntoView({ block: "nearest", inline: "nearest" });

  const takeHit = actions.find((a) => a.type === "skipEquipment");
  const portrait = player.querySelector(".player-portrait");
  if (takeHit && portrait) {
    portrait.classList.add("defense-ready");
    portrait.setAttribute(
      "aria-label",
      "Druid: take the hit and save remaining defenses",
    );
    portrait.title =
      "Click the Druid to take this hit without using remaining cards, Bracelet Guard or Armor.";
    portrait.onclick = (e) => {
      e.stopPropagation();
      if (!ctx.busy()) {
        const current = ctx.game
          .legal()
          .find((a) => a.type === "skipEquipment");
        if (current) {
          ctx.close();
          ctx.act(current);
        }
      }
    };
  }

  // Keep compact equipment spatially arranged around the portrait.
  const labels = {
    head: "Head",
    neck: "Neck",
    torso: "Armor",
    wrist1: "L wrist",
    wrist2: "R wrist",
    finger1: "L ring",
    finger2: "R ring",
  };
  player.querySelectorAll("[data-equip-slot]").forEach((slot) => {
    const label = labels[slot.dataset.equipSlot];
    slot.querySelector(".gear-label").textContent = label;
    const button = slot.querySelector(".gear-item"),
      uid = Number(button.dataset.itemUid);
    const owned = o.inventory.find((x) => x.uid === uid),
      def = items[owned?.id];
    button.setAttribute("aria-label", `${label}: ${def?.name || "Empty"}`);
    const block = actions.find(
      (a) => ["bracelet", "armor"].includes(a.type) && a.uid === uid,
    );
    if (block) {
      button.classList.add("block-available");
      button.setAttribute("aria-label", `${label}: ${block.label}`);
      button.title =
        block.label +
        " · Click to defend against this attack. " +
        (def?.text || "");
      button.onclick = (e) => {
        e.stopPropagation();
        if (!ctx.busy()) {
          ctx.close();
          ctx.act(block);
        }
      };
    }
    const bracelet =
      slot.dataset.equipSlot === "torso" && def?.effect.armor
        ? { block: o.battle.armorBlock }
        : o.battle.bracelets.find((b) => b.uid === uid);
    slot.classList.toggle("defense-empty", !!bracelet && bracelet.block <= 0);
    slot.classList.toggle(
      "attack-ready",
      !!def?.effect.firstAttackOnly &&
        o.battle.phase === "activate" &&
        o.battle.firstAttackTurn !== o.battle.turn,
    );
  });
}

board-interactions.mjs:
import {sourceSlots,formationSlots} from "./growth-rules.mjs";
import { cards, MIND_COLUMNS } from "./content.mjs";
import { cardSevered } from "./corruptions.mjs";
import {
  activationGrowth,
  chargeSources,
  conduitActive,
  defensiveElement,
  matchingNeighborSlots,
  attunementElements,
  attunementSourceElement,
  gridNeighbors,
  damageBonusNeighbors,
  squarePattern,
  cardAllowance,
  corner,
} from "./engine.mjs";
const unique = (xs) => [...new Set(xs)];
const color = (element) => `var(--${element})`;
const gradient = (elements) =>
  elements.length === 1
    ? color(elements[0])
    : `linear-gradient(135deg, ${elements.map((e, i) => `${color(e)} ${(i * 100) / elements.length}%, ${color(e)} ${((i + 1) * 100) / elements.length}%`).join(",")})`;
export function cardInteraction(b, c, i) {
  const d = cards[c.id];
  if (b.grid[i].at(-1)?.uid !== c.uid) return null;
  const neighbors = gridNeighbors(b, i);
  const attunes = !!(d.attune && !c.transmuted && c.element === d.element);
  const providers = attunes
    ? sourceSlots(b,c,i).filter(
        (j) => attunementSourceElement(b, b.grid[j].at(-1)) !== "Arcane",
      )
    : [];
  const matching =
    d.effects.matchingDamage || d.effects.matchingShield
      ? matchingNeighborSlots(b, c, i)
      : [];
  const portions = b.shields.filter(
    (p) => p.owner === c.uid && p.slot === i && p.block > 0,
  );
  const cast =
    attunes && c.lastActivatedTurn === b.turn ? c.lastActivationElement : null;
  const transmuted = !!(c.transmuted || c.element !== d.element);
  const colors = transmuted
    ? [c.element]
    : portions.length
      ? unique(portions.map((p) => p.element))
      : [cast || c.element];
  return {
    attunes,
    conduit: conduitActive(b, c),
    neighbors,
    providers,
    matching,
    pattern: d.effects.square ? squarePattern(b, c, i) : [],
    choices: attunementElements(b, c, i),
    portions,
    cast,
    transmuted,
    colors,
    bonus:
      matching.length *
      (d.effects.matchingDamage || d.effects.matchingShield || 0),
    bonusType: d.effects.matchingShield ? "block" : "damage",
  };
}
export function boardConnections(b) {
  const links = [];
  const add = (from, to, type, element, reason, owner = null, both = false) => {
    if (from === to || cardSevered(b, b.grid[from].at(-1), from) || cardSevered(b, b.grid[to].at(-1), to))
      return;
    links.push({ from, to, type, element, reason, owner, both });
  };
  const live = (c, i) => cardAllowance(b, c, i) > 0 && !c.zeroWard;
  for (const [i, stack] of b.grid.entries()) {
    const c = stack.at(-1);
    if (!c) continue;
    const d = cards[c.id],
      m = cardInteraction(b, c, i),
      active = live(c, i);
    if (active && (d.formation || d.effects.diagonalDamage))
      for (const j of d.effects.diagonalDamage ? sourceSlots(b,c,i) : formationSlots(b,c,i))
        if(b.grid[j]?.length) add(j,i,"benefit",c.element,"Formation bonus");
    if(c.ashesUntil===b.turn && c.ashesPower>0)
      for(const j of m.neighbors) if(cards[b.grid[j].at(-1).id].effects.damage || cards[b.grid[j].at(-1).id].effects.hpDamage)
        add(i,j,"benefit","Earth",`Ashen Roots +${c.ashesPower} damage`);
    if (active)
      for (const j of m.providers)
        add(
          j,
          i,
          "attune",
          attunementSourceElement(b, b.grid[j].at(-1)),
          "Attunement source or activated relay",
        );
    for (const j of m.matching)
      if (i < j || conduitActive(b, b.grid[j].at(-1))) {
        const conduit = conduitActive(b, b.grid[j].at(-1));
        const other = !conduit && live(b.grid[j].at(-1), j);
        if (active || other)
          add(
            active ? j : i,
            active ? i : j,
            "synergy",
            null,
            conduit ? "Conduit matching-card bonus" : "Matching card bonus",
            null,
            active && other,
          );
      }
    if (
      d.growth ||
      (active && (d.effects.adj || d.effects.adjHeal || d.effects.adjInsight))
    )
      for (const j of d.effects.adj &&
      !d.growth &&
      !d.effects.adjHeal &&
      !d.effects.adjInsight
        ? damageBonusNeighbors(b, c, i)
        : m.neighbors)
        add(
          j,
          i,
          "benefit",
          c.element,
          d.growth ? "Growth from neighbor" : "Adjacency bonus",
        );
    if (active && d.effects.growAfterAttack && activationGrowth(b, c, i) > 0)
      for (const j of m.neighbors)
        add(j, i, "benefit", c.element, "Growth after attack");
    if (active && d.chargeElement && c.charge < d.charge)
      for (const j of chargeSources(b, c, i))
        add(
          j,
          i,
          "benefit",
          d.chargeElement,
          "Watering: +2 Charge per activation",
        );
    if (active && d.effects.row && !cardSevered(b, c, i))
      for (const [j, other] of b.grid.entries())
        if (
          j !== i &&
          Math.floor(i / MIND_COLUMNS) === Math.floor(j / MIND_COLUMNS) &&
          other.at(-1)?.element === c.element
        )
          add(j, i, "benefit", c.element, "Same-element row damage");
    if (active && d.condition && !["corner", "isolated"].includes(d.condition))
      for (const j of m.neighbors)
        if (b.grid[j].at(-1).element === d.condition)
          add(j, i, "benefit", d.condition, "Activation requirement");
    if (d.keystone && corner(i))
      for (const [j, other] of b.grid.entries()) {
        const target = other.at(-1),
          def = cards[target?.id];
        if (
          target &&
          !def.singleUse &&
          def.limit > 0 &&
          live(target, j) &&
          (j % MIND_COLUMNS === i % MIND_COLUMNS ||
            Math.floor(j / MIND_COLUMNS) === Math.floor(i / MIND_COLUMNS))
        )
          add(i, j, "allowance", "Light", "+1 activation allowance");
      }
    if (!active || !m.pattern.length) continue;
    const [tl, tr, bl, br] = m.pattern;
    for (const [a, z] of [
      [tl, tr],
      [tl, bl],
      [tr, br],
      [bl, br],
    ])
      add(a, z, "pattern", null, "Fourfold 2×2 damage bonus", i, true);
    const opposite = m.pattern.find(
      (j) =>
        Math.floor(j / MIND_COLUMNS) !== Math.floor(i / MIND_COLUMNS) &&
        j % MIND_COLUMNS !== i % MIND_COLUMNS,
    );
    add(opposite, i, "pattern", null, "Fourfold opposite corner", i);
  }
