      "link-inspected",
      i != null &&
        (Number(link.dataset.from) === i ||
          Number(link.dataset.to) === i ||
          link.dataset.patternOwner === String(i)),
    );
}
function severBorder(slot) {
  const ns = "http://www.w3.org/2000/svg",
    w = slot.clientWidth,
    h = slot.clientHeight;
