        : z.right - 5
      : horizontal
        ? forward
          ? z.left + 13
          : z.right - 13
        : (z.left + z.right) / 2;
    const y1 = diagonal
      ? forward
        ? a.bottom - 5
        : a.top + 5
      : horizontal
        ? a.top + a.height * 0.32
        : forward
          ? a.bottom - 3
          : a.top + 3;
    const y2 = diagonal
      ? forward
        ? z.top + 5
        : z.bottom - 5
