        cardsGained: [],
        itemsGained: [],
        purchases: [],
        sales: [],
        encounters: [],
      },
      steps: 0,
    };
    for (let warmup = 0; warmup < 8; warmup++) this.rand();
    this.s.archon = this.pick(
      Object.values(enemies)
        .filter((e) => e.tier === "Archon" && (e.stratum || 1) === 1)
        .map((e) => e.id),
    );
    this.s.enemyDecks = {
      Mote: this.shuffle(
        Object.values(enemies)
          .filter(
            (e) =>
              e.tier === "Mote" &&
              (e.stratum || 1) === 1 &&
              !e.summonOnly &&
              !e.tutorialOnly,
          )
          .flatMap((e) => (e.movement === "Skittish" ? [e.id] : [e.id, e.id])),
      ),
      Eidolon: this.shuffle(
        Object.values(enemies)
          .filter(
            (e) =>
              e.tier === "Eidolon" && (e.stratum || 1) === 1 && !e.tutorialOnly,
          )
          .map((e) => e.id),
      ),
    };
    this.s.eventDeck = this.shuffle(
      events.filter((e) => e.id !== "shrine").map((e) => e.id),
    ).filter(id => this.eventPool().includes(id));
    this.s.itemDeck = this.shuffle([
      ...Object.keys(items).filter((id) => !items[id].fieldOnly && suppliesAvailable(this.s,id)),
      ...Object.keys(cards)
        .filter(
          (id) =>
            !starter.includes(id) &&
            (cards[id].stratum || 1) === 1 &&
            !cards[id].companion,
        )
        .filter((id) => !cards[id].destroyAfterActivation || this.rand() < 0.25)
        .map((id) => "card:" + id),
    ]);
