    this.addItem("bronze");
    this.addItem("ring");
    this.s.startGem = this.pick(["ruby", "emerald", "topaz", "sapphire"]);
    this.addItem(this.s.startGem);
    this.s.equipment.wrist2 = this.s.inventory[0].uid;
    this.s.equipment.finger2 = this.s.inventory[1].uid;
  }
  normalizeRewards() {
    const s = this.s;
    if (s.itemDeck) s.itemDeck = s.itemDeck.filter(id =>
      !id.startsWith("card:") || !excludedStarterOffers.has(id.slice(5)));
    if (s.reward?.cards) {
      if (
        s.reward.boss && !s.reward.apexReward &&
        (s.reward.cards.length !== 3 ||
          new Set(s.reward.cards).size !== 3 ||
          s.reward.cards.filter((id) => cards[id]?.rarity === "legendary")
            .length !== 1 ||
          s.reward.cards.filter((id) => cards[id]?.rarity === "rare").length !==
            2)
      )
        s.reward.cards = this.bossOffer();
      s.reward.cards = [...s.reward.cards];
      for (let i = 0; i < s.reward.cards.length; i++) {
        const id = s.reward.cards[i];
        if (excludedStarterOffers.has(id))
          s.reward.cards[i] = this.pool(cards[id].rarity, true).find(
            (c) => !s.reward.cards.includes(c.id),
          ).id;
      }
    }
    if (s.mode === "item" && s.itemOffer?.length > 1)
      s.itemOffer = [s.itemOffer[0]];
    if (s.reward?.gem === true)
      s.reward.gem = this.pick(this.rand()<0.25 ? Object.keys(items).filter(id=>items[id].consumable&&suppliesAvailable(s,id)) : [
        "ruby",
        "emerald",
        "topaz",
        "sapphire",
        "focusGem",
        "channelGem",
        "insightGem",
      ]);
    if (s.reward?.setting === true)
      s.reward.setting = this.pick(s.stratum>=2&&this.rand()<0.5 ? Object.keys(items).filter(id=>items[id].expansion==="supplies"&&!items[id].consumable&&suppliesAvailable(s,id)) : [
        "silver",
        "channelRing",
        "focusRing",
        "necklace",
      ]);
  }
  normalizeShop() {
    const stock = this.s.shop?.stock;
    if (!stock) return;
    for (let i = 0; i < stock.length; i++) {
      const id = stock[i].startsWith("card:") ? stock[i].slice(5) : null;
      if (!excludedStarterOffers.has(id)) continue;
      const replacement = this.pool(cards[id].rarity, true).find(
        (c) => !stock.includes("card:" + c.id),
      );
      // Replace only retired offers; preserve stock positions and run randomness.
      if (replacement) stock[i] = "card:" + replacement.id;
      else stock.splice(i--, 1);
    }
  }
  present(kind, detail = {}) {
    if (this.capturePresentation)
      (this.presentation ??= []).push({
        kind,
        ...detail,
        state: this.observe(),
      });
  }
  markAreaPresentation(start, slot) {
    if (!this.capturePresentation) return;
    for (const frame of this.presentation.slice(start)) {
      frame.parallelGroup = start;
      frame.sourceSlot ??= slot;
    }
  }
  rand() {
    let x = this.s.rng;
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    this.s.rng = x >>> 0;
    return this.s.rng / 4294967296;
  }
  pick(xs) {
    return xs[Math.floor(this.rand() * xs.length)];
  }
  shuffle(xs) {
    const a = [...xs];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(this.rand() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
  uid() {
    return ++this.s.uid;
  }
  newCard(id, upgrade = false) {
    return { uid: this.uid(), id, upgrade };
  }
  addCard(id) {
    const c = this.newCard(id);
    this.s.deck.push(c);
    this.s.stats.cardsGained.push(cards[id].name);
    this.log("Gained " + cards[id].name);
    return c;
  }
  addItem(id) {
    if (
      items[id].slot === "torso" &&
      this.s.inventory.filter((x) => items[x.id].slot === "torso").length >= 3
    ) {
      this.s.pendingArmor = id;
      return null;
    }
    const c = { uid: this.uid(), id, gem: null };
    this.s.inventory.push(c);
    this.s.stats.itemsGained.push(items[id].name);
    if (items[id].cursed && items[id].slot !== "gem") {
      const slots = Object.keys(this.s.equipment).filter((k) =>
        k.startsWith(items[id].slot),
      );
      const free =
        slots.find((k) => !this.s.equipment[k]) ||
        slots.find((k) => !items[this.getItem(this.s.equipment[k]).id].cursed);
      if (free) this.s.equipment[free] = c.uid;
      else c.unequippedCurse = true;
    }
    return c;
  }
  getItem(uid) {
    return this.s.inventory.find((x) => x.uid === uid);
  }
  log(msg) {
    this.decisionLog?.push(msg);
    this.s.log.push(msg);
    if (this.s.log.length > 120) this.s.log.shift();
  }
  gainGold(n) {
    this.s.gold += n;
    this.s.stats.goldEarned += n;
  }
  spend(n) {
    this.s.gold -= n;
    this.s.stats.goldSpent += n;
  }
  bonuses() {
    const sum = {
      insight: 4,
      focus: 1,
      channel: 2,
      movement: 2,
      damage: 0,
      shield: 0,
      heal: 0,
      armor: 0,
      recall: 0,
    };
    for (const uid of Object.values(this.s.equipment)) {
      const inst = this.getItem(uid);
      if (!inst) continue;
      const d = items[inst.id];
      for (const [k, v] of Object.entries(d.effect))
        if (typeof v === "number") sum[k] = (sum[k] || 0) + v;
      if (inst.gem) {
        const g = items[this.getItem(inst.gem)?.id];
        if (g)
          for (const [k, v] of Object.entries(g.effect))
            if (typeof v === "number") sum[k] = (sum[k] || 0) + v;
        if (d.synergy === g?.id) sum.heal++;
      }
    }
    for (const inst of this.s.inventory)
      if (items[inst.id].cursed && inst.unequippedCurse) sum.movement--;
    for (const k of ["insight", "focus", "channel", "movement"])
      sum[k] = Math.max(1, Math.floor(sum[k]));
    return sum;
  }
  equipped() {
    return Object.entries(this.s.equipment).flatMap(([slot, uid]) => {
      const x = this.getItem(uid);
      return x
        ? [
            {
              ...x,
              slot,
              definition: items[x.id],
              element:
                items[this.getItem(x.gem)?.id]?.element ||
                items[x.id].element ||
                "Arcane",
            },
          ]
        : [];
    });
  }
  pool(rarity = "common", reward = false) {
    return Object.values(cards).filter(
      (c) =>
        c.type !== "Hex" &&
        (!c.companion ||
          (reward && c.id === "elves" && (this.s.stratum || 1) >= 2)) &&
        (c.stratum || 1) <= (this.s.stratum || 1) &&
        c.rarity === rarity &&
        !["surge"].includes(c.id) &&
        (!reward || !excludedStarterOffers.has(c.id)),
    );
  }
  bossOffer() {
    const pool = this.pool("legendary", true).map((c) => c.id);
    if (!pool.length || this.pool("rare", true).length < 2)
      throw Error(
        "Boss rewards require one legendary and two distinct rare cards.",
      );
    return [this.pick(pool), ...this.rareOffer(2, true)];
  }
  rareOffer(count = 1, reward = true) {
    const pool = this.pool("rare", reward),
      result = [];
    while (result.length < count && pool.length) {
      const tickets = pool.flatMap((c) => Array(c.offerWeight ?? 4).fill(c.id));
      const id = this.pick(tickets);
      result.push(id);
      pool.splice(
        pool.findIndex((c) => c.id === id),
        1,
      );
    }
    return result;
  }
  offer(rare = false, reward = true, companions = reward) {
    const common = this.shuffle(
      this.pool("common", reward)
        .filter((c) => companions || !c.companion)
        .map((c) => c.id),
    ).slice(0, rare ? 2 : 3);
    return rare ? [...common, ...this.rareOffer(1, reward)] : common;
  }
  eventPool() {
    const stratum = this.s.stratum || 1;
    return events.filter(e => e.id !== "shrine" &&
      (stratum >= 3 ? e.stratum === 3 : !e.stratum || e.stratum === stratum))
      .map(e => e.id);
  }
  drawEvent() {
    const pool = this.eventPool(), allowed = new Set(pool);
    // Old saves can contain future-Stratum events. Keep the remaining legal
    // order without consuming RNG; only refill after those entries are spent.
    this.s.eventDeck = (this.s.eventDeck || []).filter(id => allowed.has(id));
    return this.drawDeck("eventDeck", pool);
  }
  drawDeck(key, source) {
    let a = this.s[key];
    if (!a.length) this.s[key] = a = this.shuffle(source);
    return a.pop();
  }
  rollSpawn(opening = false) {
    // d20: 1–10 enemy, 11–15 loot, 16–19 Event, 20 reroll.
    // Taverns are scheduled, not random. Subtypes use a separate d10.
    let category;
    do {
      category = 1 + Math.floor(this.rand() * 20);
    } while (category === 20);
    if (category <= 10) {
      const subtype = 1 + Math.floor(this.rand() * 10);
      return opening || subtype <= 8 ? "Mote" : "Eidolon";
    }
    if (category <= 15)
      return 1 + Math.floor(this.rand() * 10) <= 6 ? "Gold" : "Item";
    return "Event";
  }
  normalizeSpawns() {
    const f = this.s.field;
    if (f.spawnWidth === 2) return;
    // Retain each already revealed legacy entry as the second member of its pair.
    f.spawned *= 2;
    f.queue = f.queue.flatMap((type, i) => [
      this.rollSpawn(f.spawned / 2 + i < 4),
      type,
    ]);
    f.spawnWidth = 2;
    if (this.s.mode === "battle") this.s.battle.channel++;
    this.batch();
  }
  batch() {
    if (apexActive(this.s)) return apexBatch(this);
    const f = this.s.field;
    while (f.queue.length < Math.min(8, 32 - f.spawned)) {
      const number = f.spawned + f.queue.length + 1;
      f.queue.push(
        number === 16
          ? "Tavern"
          : number === 32
            ? "Archon"
            : this.rollSpawn(number <= 8),
      );
