        s.deck = s.deck.filter((x) => x.uid !== a.uid);
        break;
      case "removeHex":
        if (a.costs.gold) this.spend(a.costs.gold);
        if (a.costs.hp) {
          s.hp -= a.costs.hp;
          s.stats.damageTaken += a.costs.hp;
        }
        s.deck = s.deck.filter(
          (x) => x.uid !== a.uid && x.uid !== a.sacrificeCard,
        );
        if (a.sacrificeItem) this.removeItem(a.sacrificeItem);
        this.log(a.label);
        break;
      case "upgrade": {
        const c = s.deck.find((x) => x.uid === a.uid),
          u = cards[c.id].upgrade;
        if (u.gold) this.spend(u.gold);
        if (u.item) {
          const material = s.inventory.find((x) => x.id === u.item);
          s.inventory = s.inventory.filter((x) => x.uid !== material.uid);
          (s.stats.upgradeMaterials ||= []).push({
            cardUid: c.uid,
            itemUid: material.uid,
            item: material.id,
            step: s.steps,
          });
        }
        if (u.hp) {
          s.hp -= u.hp;
          s.stats.damageTaken += u.hp;
        }
        if (a.sacrifice) s.deck = s.deck.filter((x) => x.uid !== a.sacrifice);
        c.upgrade = true;
        break;
      }
      case "enterLoom":
        if (s.pendingLoomCompanion) {
          s.deck.push(s.pendingLoomCompanion.card);
          s.stats.withoutMenders = {
            ...s.pendingLoomCompanion.challenge,
            receivedAtStep: s.steps,
          };
          delete s.pendingLoomCompanion;
          this.log("Machine Elves join your Grimoire.");
        } else if (!s.stats.withoutMenders) {
          const elves = this.addCard("elves");
          s.stats.withoutMenders = {
            uid: elves.uid,
            receivedAtStep: s.steps,
            disqualified: null,
          };
        }
        delete s.loomIntro;
        this.beginRound();
        break;
      case "placeStrike": {
        const c = b.hand.find(c=>c.uid===a.uid), e = hostiles(b).find(e=>e.uid===a.target);
        b.focus -= a.costs.focus;
        b.hand = b.hand.filter(x=>x.uid!==c.uid);
        b.discard.push(c);
        this.present("activate", {name:cards[c.id].name, card:c.uid, slot:e.ideon?e.slot:null});
        this.damageEnemy(e,a.effects.damage,c.element||cards[c.id].element,{});
        this.log(`${cards[c.id].name} strikes and returns to Discard.`);
        drainLeeches(this); this.checkBattle(); if(s.mode==="battle") this.pump();
        break;
      }
      case "place": {
        const c = b.hand.find((x) => x.uid === a.uid),
          d = cards[c.id];
        b.hand = b.hand.filter((x) => x.uid !== a.uid);
        b.focus -= a.costs.focus;
        b.milky = false;
        const slot = b.grid[a.slot];
        if (d.stack === "returnHand") {
          b.hand.push(
            ...slot.map((x) => ({ uid: x.uid, id: x.id, upgrade: x.upgrade })),
          );
          b.grid[a.slot] = [];
          b.discard.push({ uid: c.uid, id: c.id, upgrade: c.upgrade });
          this.present("recall", {
            slot: a.slot,
            name: "Undertow · returned to hand",
          });
          this.log(
            `Undertow returns ${slot.length} card(s) to hand for ${a.costs.focus} Focus; Undertow goes to discard.`,
          );
          break;
        }
        const inst = this.instance(c);
        if (a.placementElement) {
          inst.element = a.placementElement;
          inst.chosenElement = true;
        }
        if (
          [
            "reinforce",
            "heatMeld",
            "plasmaMeld",
            "recallDiscount",
            "latticeMeld",
          ].includes(d.stack) &&
          slot.length
        ) {
          const host = top(slot);
          inst.attachedTo = host.uid;
          inst.ward = 0;
          slot.splice(slot.length - 1, 0, inst);
          if (d.stack === "reinforce") {
            const revived = host.zeroWard || host.ward <= 0;
            if (revived) {
              host.ward = 1;
              host.zeroWard = false;
            }
            this.log(
              `${d.name} reinforces ${cards[host.id].name}: +1 activation allowance${revived ? "; restored 1 Ward" : ""}.`,
            );
            this.present("status", {
              target: "card",
              slot: a.slot,
              name: revived
                ? "Reinforced · +1 use · 1 Ward restored"
                : "Reinforced · +1 use",
            });
          } else if (d.stack === "recallDiscount") {
            this.log("Palimpsest stores 1 Focus toward this stack's Recall.");
            this.present("status", {
              target: "card",
              slot: a.slot,
              name: "Recall cost −1",
            });
          } else if (d.stack === "latticeMeld") {
            host.ward += 5;
            host.zeroWard = false;
            host.element = a.placementElement;
            host.chosenElement = true;
            host.transmuted = true;
            this.log(
              `Living Lattice adds 5 Ward and changes its host to ${a.placementElement} until recalled or destroyed.`,
            );
            this.present("status", {
              target: "card",
              slot: a.slot,
              name: `+5 ${a.placementElement} Ward · revived`,
            });
          } else if (d.stack === "plasmaMeld") {
            this.log(
              `Plasma Ball melds beneath its host: ${this.cardPower(host, a.slot)} damage, +1 activation allowance, +1 Recall Focus.`,
            );
            this.present("status", {
              target: "card",
              slot: a.slot,
              name: "Plasma melded · +1 use · +1 Recall",
            });
          } else {
            this.log(
              `Heat melds beneath ${cards[host.id].name}: Burn ${cardEffects(inst).burn + (inst.upgrade ? d.upgrade.bonus : 0)} on its next two attack activations.`,
            );
            this.present("status", {
              target: "card",
              slot: a.slot,
              name: "Heat melded · 2 attack uses",
            });
          }
        } else slot.push(inst);
        if (
          d.bondHP &&
          this.neighbors(a.slot).some((j) => top(b.grid[j]).element === "Earth")
        )
          inst.hp += d.bondHP;
        inst.maxHp = Math.max(inst.maxHp, inst.hp);
        capAllyHP(inst);
        if (d.onPlaceCharge)
          inst.charge = Math.min(
            d.charge,
            this.neighbors(a.slot).filter(
              (j) => top(b.grid[j]).element === "Fire",
            ).length,
          );
        if (d.onPlaceFocus) b.focus += d.onPlaceFocus;
        break;
      }
      case "recall":
        b.recallCount=Math.min(2,(b.recallCount||0)+1);
        b.shields=b.shields.filter(x=>x.slot!==a.slot);
        b.focus -= a.costs.focus;
        b.discard.push(
          ...b.grid[a.slot].map((c) => ({
            uid: c.uid,
            id: c.id,
            upgrade: c.upgrade,
          })),
        );
        b.grid[a.slot] = [];
        break;
      case "activatePhase":
        b.discard.push(...b.hand);
        b.hand = [];
        b.phase = "activate";
        break;
      case "activate":
        this.activate(a);
        break;
      case "endTurn":
        this.endTurn();
        break;
      case "ward": {
        const c = b.grid[a.slot].find((c) => c.uid === a.uid),
          h = b.reaction;
        const result = blockHit(
          c.ward,
          defensiveElement(b, c),
          h.damage,
          h.element,
        );
        const stopped = h.damage - result.remaining;
        const loss = c.ward - result.block;
        c.ward = result.block;
        h.damage = result.remaining;
        h.weaknessBonus = 0;
        h.weaknessElement = null;
        if (!c.ward) c.zeroWard = true;
        this.presentIncomingNode(
          "defend",
          { slot: a.slot, amount: stopped, loss, name: "Ward absorbs" },
          { kind: "card", slot: a.slot },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "block":
      case "bracelet": {
        const p = (a.type === "block" ? b.shields : b.bracelets).find(
          (x) => x.uid === a.uid,
        );
        b.reaction.weaknessBonus = 0;
        b.reaction.weaknessElement = null;
        const r = blockHit(
          p.block,
          p.element,
          b.reaction.damage,
          b.reaction.element,
        );
        const stopped = b.reaction.damage - r.remaining;
        const loss = p.block - r.block;
        p.block = r.block;
        b.reaction.damage = r.remaining;
        this.presentIncomingNode(
          "defend",
          {
            slot: a.type === "block" ? p.slot : null,
            item: a.type === "bracelet" ? a.uid : null,
            amount: stopped,
            loss,
            name: "Absorbed",
          },
          a.type === "block"
            ? { kind: "card", slot: p.slot }
            : { kind: "item", uid: a.uid },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "playerGuard": {
        const h = b.reaction, before = b.bodyGuard;
        const r = blockHit(before,"Arcane",h.damage,h.element);
        const stopped = h.damage-r.remaining;
        b.bodyGuard=r.block; h.damage=r.remaining; h.weaknessBonus=0; h.weaknessElement=null;
        this.presentIncomingNode("defend",{target:"player", amount:stopped, loss:before-r.block,name:"Player Guard"},{kind:"bodyGuard"});
        this.advanceHit(); this.pump(); break;
      }
      case "armor": {
        const h = b.reaction;
        const armor = this.defenseChoices().armors.find((x) => x.uid === a.uid);
        let loss;
        h.weaknessBonus = 0;
        h.weaknessElement = null;
        const result = armor.reflect
          ? { remaining: 0, block: b.armorBlock }
          : blockHit(b.armorBlock, armor.element, h.damage, h.element);
        const stopped = h.damage - result.remaining;
        loss = armor.reflect ? stopped : b.armorBlock - result.block;
        b.armorBlock = result.block;
        if (armor.reflect) {
          b.mirror = true;
        }
        h.damage -= stopped;
        this.presentIncomingNode(
          "defend",
          {
            item: a.uid,
            amount: stopped,
            loss,
            name: armor.reflect ? "Reflected" : "Armor protects",
          },
          { kind: "item", uid: a.uid },
        );
        if (armor.reflect)
          this.damageEnemy(
            b.enemies.find((e) => e.uid === h.source),
            stopped,
            h.element,
            {},
            a.uid,
          );
        this.advanceHit();
        this.pump();
        break;
      }
      case "intercept":
        this.intercept(a.slot);
        this.pump();
        break;
      case "skipEquipment":
        this.log("You let the hit through without using remaining defenses.");
        b.reaction.stage = "player";
        this.advanceHit();
        this.pump();
        break;
      case "takeHit":
        b.reaction.column = -1;
        b.reaction.stage = "bracelet";
        this.advanceHit();
        this.pump();
        break;
    }
    if (
      s.pendingPickupResolution &&
      satchelContents(s).length <= SATCHEL_CAPACITY
    ) {
      delete s.pendingPickupResolution;
      this.resolveTile();
    }
    if (b) resetCoveredInsanity(b);
    if (openBefore && s.battle === b && s.mode === "battle")
      retargetCoveredCorruptions(
        this,
        b.grid.flatMap((stack, i) =>
          openBefore[i] && stack.length ? [i] : [],
        ),
      );
    if (a.type === "place" && s.mode === "battle") drainLeeches(this);
    const challenge = s.stats.withoutMenders;
    if (challenge && !challenge.disqualified) {
      if (!s.deck.some((c) => c.uid === challenge.uid))
        challenge.disqualified = "companion removed";
      if (
        (a.type === "place" &&
          b?.grid[a.slot]?.some((c) => c.id === "elves")) ||
        (a.type === "activate" &&
          b?.grid[a.slot]?.some((c) => c.id === "elves"))
      )
        challenge.disqualified = "Machine Elves used";
    }
    if (s.checkpoint && challenge)
      s.checkpoint.stats.withoutMenders = clone(challenge);
    finishInspiration(this,a);
    refreshBossPlans(this);
    tutorialAfter(this, a);
    return this.observe();
  }
  removeItem(uid) {
    const s = this.s;
    for (const k of Object.keys(s.equipment))
      if (s.equipment[k] === uid) s.equipment[k] = null;
    for (const x of s.inventory) if (x.gem === uid) x.gem = null;
    s.inventory = s.inventory.filter((x) => x.uid !== uid);
  }
  observe() {
    const s = this.s;
    const o = {
      version: VERSION,
      stratum: s.stratum || 1,
      stratumName: STRATA[s.stratum || 1].name,
      loomIntro: s.loomIntro,
      depthsIntro: s.depthsIntro,
      apexIntro: s.apexIntro,
      apex: s.apex ? clone(s.apex) : null,
      tutorial: s.tutorial
        ? {
            id: s.tutorial.id,
            version: s.tutorial.version,
            name: s.tutorial.name,
            completed: s.tutorial.completed,
            fight: s.tutorial.fight,
            step: s.tutorial.step,
            lesson: s.tutorial.lesson,
            guide: tutorialGuide(this),
          }
        : null,
      mode: s.mode,
      classId: s.classId,
      hp: Math.max(0, s.hp),
      maxHp: s.maxHp,
      gold: s.gold,
      deck: clone(s.deck),
      inventory: clone(s.inventory),
      satchel: { used: satchelContents(s).length, capacity: SATCHEL_CAPACITY },
      equipment: clone(s.equipment),
      bonuses: this.bonuses(),
      status: clone(s.status),
      field: clone(s.field),
      log: s.log.slice(-30),
      steps: s.steps,
      stats: clone(s.stats),
      startGem: s.startGem,
      archon: s.revealedArchon ? enemies[s.revealedArchon].name : null,
      pendingArmor: s.pendingArmor,
      nextHealerHint: s.nextHealerHint,
    };
    if (s.mode === "battle") {
      o.battle = clone(s.battle);
      o.battle.ideons = (o.battle.ideons || []).map(e => ({ ...e, text: ideonText(e) }));
      delete o.battle.jobs;
      o.battle.telegraphs = this.gridTelegraphs();
      o.battle.angerTargets = Object.entries(s.battle.corruptions || {}).flatMap(([slot, q]) => {
        if (q.kind !== "anger") return [];
        const a = angerPreview(this, Number(slot));
        return a ? [{ from: Number(slot), to: a.slot }] : [];
      });
      o.battle.deck.sort((a, b) => a.id.localeCompare(b.id) || a.uid - b.uid);
      o.battle.enemies = o.battle.enemies
        .filter((e) => e.hp > 0 || (enemies[e.id].onDeath && !e.deathResolved))
        .map((e) => ({
          ...e,
          hp: Math.max(0, e.hp),
          statusImmunity: enemyStatusImmunity(e),
          statusImmunities: enemyStatusImmunities(e),
          signature:
            pressureSignature(enemies[e.id].signature, e) +
            (enemyStatusImmunity(e)
              ? ` Immune to ${statusName(enemyStatusImmunity(e))} while ${e.element}.`
              : ""),
          counter: enemies[e.id].counter,
          rotation: enemies[e.id].rotation.map((t) => ({
            ...pressureTell(clone(t), e),
            ...(t.currentElement ? { element: e.element } : {}),
          })),
          onDeath: enemies[e.id].onDeath && pressureTell(enemies[e.id].onDeath, e),
          tell: e.hp <= 0 ? pressureTell(enemies[e.id].onDeath, e) : this.tell(e),
        }));
    }
    if (s.mode === "event") o.event = events.find((e) => e.id === s.event);
    if (s.mode === "tavern") o.shop = clone(s.shop);
    if (s.mode === "item") o.itemOffer = clone(s.itemOffer);
    if (s.mode === "reward") o.reward = clone(s.reward);
    if (s.mode === "result") {
      o.outcome = s.outcome;
      o.cause = s.cause;
      o.death = clone(s.death);
      o.seed = s.seed;
      o.history = clone(s.history);
    }
    return o;
  }
  save() {
    return clone(
      this.s.mode === "battle" && this.s.checkpoint && !this.s.tutorial
        ? this.s.checkpoint
        : this.s,
    );
  }
}

field-display.mjs:
import { enemies, items } from "./content.mjs";

// Display priority only: never reorder the Field's encounter or movement state.
export function fieldEntitiesAt(field, x, y) {
  const priority = (e) =>
    enemies[e.enemy]?.tier === "Archon"
      ? 3
      : e.enemy
        ? 2
        : (items[e.item]?.consumable || e.fieldSupply)
          ? 1
          : 0;
  return field.entities
    .filter((e) => e.x === x && e.y === y)
    .sort((a, b) => priority(b) - priority(a));
}

growth-policy.mjs:
import { cards } from "./content.mjs";
import { formationReady, formationSlots, diagonals } from "./growth-rules.mjs";
import { enemyDamage, hasDirectDamageActivation, adjacent } from "./engine.mjs";
// Small feature adjustments; all actions still come from the authoritative legal list.
export function growthScore(o, a) {
  const b = o.battle;
  if (!b) return 0;
  const d = cards[a.effects.card],
    f = a.effects;
  if (a.type === "placeStrike") {
    const e = [...b.enemies, ...(b.ideons || [])].find(
      (e) => e.uid === a.target,
    );
    const n = enemyDamage(f.damage, f.element, e);
    return Math.min(e.hp, n) + (n >= e.hp ? 12 : 0) - a.costs.focus * 2;
  }
  if (a.type === "place" && d?.expansion === "growth") {
    let n = 0;
    if(d.effects.forked || d.effects.ivy){
      const targets=(b.ideons||[]).filter(e=>e.hp>0&&adjacent(a.slot).includes(e.slot));
      const edgeShot=d.effects.forked&&a.slot%7===6&&b.enemies.some(e=>!e.hive);
      n+=targets.length?12+targets.length*3:edgeShot?10:-22;
    }
    if (d.formation) {
      const copy = {
        ...b,
        grid: b.grid.map((s, i) =>
          i === a.slot ? [{ id: d.id, element: d.element }] : s,
        ),
      };
      const slots = formationSlots(copy, { id: d.id }, a.slot),
        filled = slots.filter((i) => copy.grid[i]?.length).length;
      n += formationReady(copy, { id: d.id }, a.slot) ? 14 : -28 + filled * 4;
    }
    if (d.diagonalAttune)
      n += diagonals(a.slot).filter((i) => b.grid[i].length).length * 4;
    if (d.effects.borrowInsight)
      n +=
        b.grid.filter(
          (s) => s.length && s.at(-1).used < cards[s.at(-1).id].limit,
        ).length > 2
          ? 5
          : -8;
    if (d.effects.ashesBuff)
      n +=
        Math.min(6, b.destroyed.length) *
          adjacent(a.slot).filter(
            (i) =>
              b.grid[i].length && hasDirectDamageActivation(b.grid[i].at(-1)),
          ).length -
        10;
    if (d.id === "memoryAcorn") n -= 4; // Taking it out of Draw gives up its passive Insight.
    return n;
  }
  if (a.type !== "activate") return 0;
  let n = 0;
  if (f.borrowInsight) n -= 8;
  if (f.loseFocus) n -= b.turn < 5 ? 24 : 12;
  if (f.spendFocus) n -= f.spendFocus;
  if (f.focusSpend) n -= f.focusSpend * 1.2;
  if (f.bodyGuard)
    n += Math.min(
      f.bodyGuard,
      b.enemies.reduce((sum, e) => sum + (e.tell?.damage || 0), 0),
    );
  if (f.ashesBuff)
    n +=
      Math.min(6, b.destroyed.length) *
      adjacent(a.slot).filter((i) => {
        const c = b.grid[i].at(-1);
        return (
          c &&
          hasDirectDamageActivation(c) &&
          c.lastActivatedTurn !== b.turn &&
          c.used < cards[c.id].limit
        );
      }).length;
  if (f.fracture) {
    const target = [...b.enemies, ...(b.ideons || [])].find(
      (e) => e.uid === a.target,
    );
    n += target.chaosFracture
      ? -15
      : b.grid.some(
            (s) =>
              s.at(-1)?.element === "Chaos" &&
              hasDirectDamageActivation(s.at(-1)),
          )
        ? 6
        : -4;
  }
  if (a.secondaryElement) {
    const target = [...b.enemies, ...(b.ideons || [])].find(
      (e) => e.uid === a.target,
    );
    n += target ? enemyDamage(f.damage, a.secondaryElement, target) : 0;
  }
  if (f.route)
    n +=
      f.route.reduce((sum, p) => {
        const e = [...b.enemies, ...(b.ideons || [])].find(
          (e) => e.uid === p.uid,
        );
        return sum + Math.min(e.hp, enemyDamage(p.damage, a.element, e));
      }, 0) - f.damage;
  return n;
}

growth-rules.mjs:
import { protectedOwner, ideonActivationReason } from "./ideons.mjs";
import {
  cards,
  enemies,
  MIND_COLUMNS as W,
  MIND_ROWS as H,
} from "./content.mjs";
import { cardSevered, corruptionPower } from "./corruptions.mjs";
import {
  adjacent,
  attunementSourceElement,
  gridNeighbors,
  hasDirectDamageActivation,
} from "./engine.mjs";
const top = (s) => s?.at(-1);
export const destroyedCount = (b) => (b.destroyed || []).length;
export const acornIn = (b, pile) =>
  (b[pile] || []).some((c) => c.id === "memoryAcorn");
export function diagonals(i) {
  const x = i % W,
    y = Math.floor(i / W);
  return [
    [-1, -1],
    [1, -1],
    [-1, 1],
    [1, 1],
  ].flatMap(([dx, dy]) =>
    x + dx >= 0 && x + dx < W && y + dy >= 0 && y + dy < H
      ? [(y + dy) * W + x + dx]
      : [],
  );
}
export function sourceSlots(b, c, i) {
  const candidates = cards[c.id].diagonalAttune ? diagonals(i) : adjacent(i);
  return cardSevered(b, c, i)
    ? []
    : candidates.filter(
        (j) => top(b.grid[j]) && !cardSevered(b, top(b.grid[j]), j),
      );
}
export function formationSlots(b, c, i) {
  const form = cards[c.id].formation,
    x = i % W,
    y = Math.floor(i / W);
  if (form === "row") return Array.from({ length: W }, (_, k) => y * W + k);
  if (form === "column") return Array.from({ length: H }, (_, k) => k * W + x);
  return form === "horizontal"
    ? [i - 1, i + 1]
    : form === "vertical"
      ? [i - W, i + W]
      : [];
}
export function formationReady(b, c, i) {
  const form = cards[c.id].formation;
  if (!form) return true;
  if (cardSevered(b, c, i)) return false;
  const player = (j) =>
    j >= 0 &&
    j < W * H &&
    top(b.grid[j]) &&
    !cardSevered(b, top(b.grid[j]), j) &&
    !(b.ideons || []).some((e) => e.hp > 0 && e.slot === j);
  if (["row", "column"].includes(form))
    return formationSlots(b, c, i).every(player);
  if (adjacent(i).length !== 4) return false;
  const filled = formationSlots(b, c, i),
    empty = adjacent(i).filter((j) => !filled.includes(j));
  return (
    filled.every(player) &&
    empty.every(
      (j) =>
        !b.grid[j].length &&
        !(b.ideons || []).some((e) => e.hp > 0 && e.slot === j),
    )
