}
export function ashesBonus(b, c, i) {
  if (!hasDirectDamageActivation(c)) return 0;
  return Math.max(
    0,
    ...gridNeighbors(b, i).map((j) => {
      const p = top(b.grid[j]);
      return p.ashesUntil === b.turn ? p.ashesPower || 0 : 0;
    }),
