import { adjacent } from "./engine.mjs";
import { coveredByIdeon, fieldIdeons, stickyAt, tendrilPlan, tendrilDamage, ideonDamage } from "./ideons.mjs";
import { artPaths } from "./art-paths.mjs";
import { cards } from "./content.mjs";
const tones = {
  Arcane: "#cbd0de",
  Fire: "#ff9b58",
  Water: "#79caff",
  Earth: "#93c37c",
  Wind: "#c6e6c0",
  Light: "#f9df81",
  Chaos: "#bf94f4",
};
const fieldNames = {
  shared: "One card",
  destroy: "Destruction",
};
const fieldName = (e) => e.field === "element" ? e.element : fieldNames[e.field];
export function enhanceIdeons(ctx) {
  const { o, app, esc, img } = ctx,
    b = o.battle;
  app.classList.toggle("in-depths", o.stratum === 3);
  if (!b) return;
  for (const el of app.querySelectorAll(".slot[data-slot]")) {
    const i = Number(el.dataset.slot),
      fields = fieldIdeons(b, i);
    el.classList.toggle("ideon-covered", coveredByIdeon(b, i));
    const returns = (b.tendrilReturns || []).filter(q => q.slot === i);
    if (returns.length) {
      const due = Math.min(...returns.map(q => q.due));
      const help = `Tendril return: fixed space. ${due > b.turn ? "One full player turn of reprieve; emerges on the following enemy turn." : "Emerges this enemy turn."} Destroys the entire card or Construct here. Recall or move it to safety; replacing it does not move this warning.`;
      el.classList.add("corruption-mark", "corruption-fixed", "tendril-return");
      el.dataset.tooltip = (el.dataset.tooltip || "") + " " + help;
      const mark = document.createElement("span");
      mark.className = "corruption-foretell tendril-return-mark";
      mark.tabIndex = 0;
      mark.dataset.tooltip = help;
      mark.setAttribute("aria-label", help);
      mark.textContent = due > b.turn ? "Tendril · 1 turn" : "Tendril · incoming";
      el.append(mark);
    }
    if (stickyAt(b, i)) {
      el.classList.add("ideon-bound");
      el.dataset.tooltip =
        (el.dataset.tooltip || "") +
        " Adjacent Clinging Thought prevents Recall.";
    }
    for (const field of fields) {
      const ring = document.createElement("span");
      ring.className = "refraction-field";
      ring.style.setProperty("--field-color", tones[field.element]);
      ring.dataset.tooltip = `${fieldName(field)} field · 2-space diamond · ${field.field === "element" ? "Only " + field.element + " activations" : field.field === "shared" ? "One card may activate here each turn" : "Activating destroys the card afterward"}`;
      el.append(ring);
    }
  }
  for (const e of b.ideons || []) {
    if (e.hp <= 0) continue;
    const cell = app.querySelector(`.slot[data-slot="${e.slot}"]`);
    if (!cell) continue;
    const owner = b.enemies.find((x) => x.uid === e.owner);
    const el = document.createElement("button");
    el.className =
      "ideon" + (e.behavior === "bullet" ? " ideon-projectile" : "");
    el.dataset.enemyUid = e.uid;
    el.dataset.ideon = e.kind;
    el.style.setProperty("--ideon-color", tones[e.element]);
    const state = Object.entries(e.status || {})
      .filter(([, v]) => v)
      .map(([k, v]) => k + " " + v)
      .join(" · ");
