    core: '<path d="M53 4c12 24-7 25 0 41 7-3 11-12 10-21 26 20 31 60-11 71C13 87 7 63 27 37c-1 15 6 19 12 14C31 29 48 22 53 4Z"/>',
    spark: "ember",
  },
  Water: {
