    core: '<g fill="none" stroke="currentColor" stroke-width="4"><circle cx="50" cy="50" r="16"/><circle cx="50" cy="50" r="31"/><path d="M5 50a45 45 0 0 1 45-45M95 50a45 45 0 0 1-45 45"/></g>',
