  },
  Wind: {
    color: "#b8e8d6",
    core: '<g fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"><path d="M6 42c19-28 61-28 74-9 10 15-8 28-16 15M11 61c20 27 61 24 77 1M27 91c25 3 56-11 66-32"/></g>',
