    "keydown",
    (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopImmediatePropagation();
        clearTargeting();
      } else if (["Enter", " "].includes(e.key)) {
        const choice = choiceAt(e.target);
        if (choice) {
          e.preventDefault();
          e.stopImmediatePropagation();
          dragging = false;
          select(options.get(choice));
        }
      }
    },
    { capture: true, signal },
  );
