      const i = tabs.indexOf(el);
      const next =
        e.key === "ArrowRight"
          ? (i + 1) % tabs.length
          : e.key === "ArrowLeft"
            ? (i + tabs.length - 1) % tabs.length
            : e.key === "Home"
              ? 0
              : e.key === "End"
                ? tabs.length - 1
                : null;
      if (next == null) return;
      e.preventDefault();
      const category = tabs[next].dataset.marketCategory;
      tabs[next].click();
      ctx.app.querySelector(`[data-market-category="${category}"]`)?.focus();
