          const badge = el.querySelector(".level");
          const uses = heats.reduce(
            (n, x) => n + Math.max(0, cards.heat.limit - x.used),
            0,
          );
          badge.textContent = `${c.id === "plasma" ? "Plasma + " : ""}Heat ${uses}/${heats.length * cards.heat.limit}`;
          badge.dataset.tooltip = `Melded Heat: ${uses} attack uses remain. Adds Burn ${attachedBurn(b, c, i)} to the host's attack targets. No extra Channel; recalls and is destroyed with its host.`;
        }
        el.querySelector(".name").textContent =
          cardName(c) + (c.upgrade ? " +" : "");
        el.dataset.element = c.element;
        const badges = statusBadges(ctx, c, i);
        if (badges) {
          el.classList.add("has-statuses");
          el.insertAdjacentHTML("beforeend", badges);
          el.style.setProperty(
            "--status-rows",
            Math.ceil(el.querySelectorAll(".card-status").length / 3),
          );
        }
        const nums = el.querySelector(".nums");
        nums.innerHTML = `${d.type === "Ward" ? "Ward " + c.ward + " · " : ""}<b>${left === Infinity ? "∞" : left}/${d.limit < 0 ? "∞" : ctx.game.allowance({ ...c, used: 0 }, i)} acts</b>${d.charge ? `<span class="charge-meter">Charge ${c.charge}/${d.charge}${left === 0 ? " · Spent" : c.charge >= d.charge ? " · Ready" : ""}</span>` : ""}`;
        if (d.type === "Ally") {
          const maximum = Math.max(
            c.hp,
            c.maxHp || d.hp + (c.upgrade ? d.upgrade?.bonus || 0 : 0),
          );
          const ratio = Math.max(0, c.hp / maximum);
          el.classList.add("ally-slot");
          nums.insertAdjacentHTML(
            "afterbegin",
            `<div class="ally-health ${ratio <= 0.3 ? "critical" : ratio <= 0.6 ? "wounded" : ""}" role="meter" aria-label="${ctx.esc(d.name)} health" aria-valuemin="0" aria-valuemax="${maximum}" aria-valuenow="${Math.max(0, c.hp)}"><i style="width:${ratio * 100}%"></i><span>${c.hp} / ${maximum} HP</span></div>`,
          );
        }
        el.draggable = can;
        el.ondragstart = (e) => {
          if (ctx.busy() || !can) {
            e.preventDefault();
            return;
          }
          drag = { activation: i };
          e.dataTransfer.setData("text/plain", JSON.stringify(drag));
          activationChooser(ctx, i, true);
        };
        el.ondragend = () => {
          drag = null;
        };
        el.insertAdjacentHTML(
          "beforeend",
          `<button class="slot-activate ${can ? "available" : ""}" data-activate-slot="${i}" aria-disabled="${!can}" title="${ctx.esc(can ? cardText(d, ctx.o.stratum) : whyDisabled(ctx, c, i))}">${c.attachedTo != null ? "Melded · activate the host" : c.zeroWard ? DEPLETED_WARD_TEXT : (d.charge ? "" : "Activate · ") + effect(c, i, ctx)}</button>`,
        );
        const activationChoices = actions.filter(
          (a) => a.type === "activate" && a.slot === i,
        );
        if (
          activationChoices.length === 1 &&
          ["target", "cardTarget", "destination", "newElement"].some(
            (k) => activationChoices[0][k] != null,
          )
        )
          el.querySelector(".slot-activate").title +=
            " Double-click to apply to the only legal target.";
        el.querySelector(".slot-activate").onclick = (e) => {
          stop(e);
          if (!ctx.busy() && can && e.detail < 2) activationChooser(ctx, i);
        };
      }
      el.onclick = (e) => {
        if (ctx.busy()) return;
        const a = game
          .legal()
          .find(
            (a) =>
              a.type === "place" &&
              a.slot === i &&
              app
                .querySelector(`[data-hand="${a.uid}"]`)
                ?.classList.contains("selected"),
          );
        if (a && !(game.s.tutorial?.lesson === "shield-place" && e.detail > 0))
          placementChooser(ctx, a);
        else if (c) showCard(ctx, c, i);
      };
      el.onkeydown = (e) => {
        if (e.target === el && ["Enter", " "].includes(e.key)) {
          e.preventDefault();
          el.click();
        }
      };
      el.ondragover = (e) => {
        if (
          drag?.card &&
          actions.some(
            (a) => a.type === "place" && a.uid === drag.card && a.slot === i,
          )
        ) {
          e.preventDefault();
          el.classList.add("drop-ready");
        }
      };
      el.ondragleave = () => el.classList.remove("drop-ready");
      el.ondrop = (e) => {
        e.preventDefault();
        const a = actions.find(
          (a) => a.type === "place" && a.uid === drag?.card && a.slot === i,
        );
        drag = null;
        if (a) placementChooser(ctx, a);
      };
    });
    const hints = section.querySelectorAll(".row.spread>small");
    hints.forEach((el) => {
      if (
        el.textContent.startsWith("Choose a revealed") ||
        el.textContent.startsWith("Click a placed")
      )
        el.textContent =
          b.phase === "place"
            ? "Placement"
            : activation
              ? "Activation"
              : "No activations available";
    });
    if (b.reaction) {
      const box = section.querySelector(".incoming-attack");
      if (box) {
        box.classList.add("incoming-attack");
        box.insertAdjacentHTML(
          "afterbegin",
          '<button class="inspect-attack">Incoming attack ↘</button>',
        );
        box.querySelector(".inspect-attack").onclick = () =>
          incomingDetails(ctx);
        box
          .querySelectorAll("[data-action]")
          .forEach((el) => (el.onclick = () => run(ctx, el.dataset.action)));
      }
    }
  }
  if (o.mode === "event") {
    eventTrades(ctx);
    const scene = app.querySelector(".scene");
    scene?.insertAdjacentHTML(
      "beforeend",
      `<aside class="event-gear">${playerMarkup(ctx)}</aside>`,
    );
  }
  if (o.mode === "tavern") tavern(ctx);
  if (o.mode === "reward" || o.mode === "item") {
    const title = app.querySelector(".layout>section>h2");
    title?.insertAdjacentHTML(
      "afterend",
      `<p class="reward-rule">${o.reward?.cards ? "Choose ONE card · the other cards are left behind" : o.mode === "item" ? (actions.some((a) => a.type === "usePickup") ? "Collect, drink now, or leave this item" : "Collect or leave this item") : o.reward?.gem || o.reward?.setting ? "Your reward · collect this item" : "All rewards collected"}</p>`,
    );
    app.querySelectorAll(".catalog [data-action]").forEach((el) => {
      const a = actions.find((a) => a.key === el.dataset.action);
      if (a)
        el.textContent =
          a.type === "rewardCard"
            ? "Choose this card"
            : a.type === "usePickup"
              ? a.label
              : "Collect";
    });
  }
  bindEquipment(ctx, app);
  if (o.mode === "battle") {
    arrangeBattle(ctx);
    enhanceIdeons(ctx);
    bindActions(ctx,app.querySelector('.battle-player'));
    const strikeFor=el=>game.legal().find(a=>a.type==='placeStrike'&&a.target===Number(el.dataset.enemyUid)&&(a.uid===drag?.card||app.querySelector(`[data-hand="${a.uid}"]`)?.classList.contains('selected')));
    app.querySelectorAll('[data-enemy-uid]').forEach(el=>{
      const selected=strikeFor(el);el.classList.toggle('target-option',!!selected);
      el.addEventListener('click',e=>{const a=strikeFor(el);if(a){e.preventDefault();e.stopImmediatePropagation();run(ctx,a);}},{capture:true});
      el.addEventListener('dragover',e=>{if(strikeFor(el)){e.preventDefault();el.classList.add('target-option');}},{capture:true});
      el.addEventListener('drop',e=>{const a=strikeFor(el);if(a){e.preventDefault();e.stopImmediatePropagation();drag=null;run(ctx,a);}},{capture:true});
      const enemy=[...o.battle.enemies,...(o.battle.ideons||[])].find(x=>x.uid===Number(el.dataset.enemyUid));
      if(enemy?.chaosFracture)el.insertAdjacentHTML('beforeend','<span class="fracture-status" data-tooltip="Additionally weak to Chaos for the next attack activation that hits. A different element consumes this too.">Chaos Fracture</span>');
    });
    boardInteractions(ctx);
    gridTelegraphs(ctx);
    if (o.battle.reaction) {
      const b = o.battle;
      app.querySelectorAll("[data-slot]").forEach((el) => {
        const i = Number(el.dataset.slot),
          c = b.grid[i].at(-1);
        if (!c) return;
        const options = () =>
          game
            .legal()
            .filter(
              (a) =>
                ["ward", "block", "intercept"].includes(a.type) && a.slot === i,
            );
        const available = options();
        const tutorialWaiting =
          o.tutorial &&
          !available.length &&
          game
            .baseLegal()
            .some(
              (a) =>
                ["ward", "block", "intercept"].includes(a.type) && a.slot === i,
            );
        const control = el.querySelector(".slot-activate");
        if (control) {
          control.textContent = available.length
            ? "Defend"
            : tutorialWaiting
              ? "Later in lesson"
              : "Cannot defend";
          control.classList.toggle("available", !!available.length);
          control.setAttribute("aria-disabled", !available.length);
          control.removeAttribute("data-activate-slot");
        }
        const defend = (e) => {
          e?.stopPropagation();
          if (ctx.busy()) return;
          const choices = options();
          if (choices.length === 1) {
            run(ctx, choices[0]);
            return;
          }
          if (!choices.length) return;
          // Only mixed portions/covered Wards need a second choice, beside their card.
          app.querySelectorAll(".defense-options").forEach((x) => x.remove());
          const menu = document.createElement("div");
          menu.className = "defense-options";
          menu.innerHTML =
            choices.map((a) => button(ctx, a)).join("") +
            "<button data-defense-cancel>Cancel</button>";
          menu.onclick = (e) => e.stopPropagation();
          el.append(menu);
          menu.querySelectorAll("[data-action]").forEach(
            (btn) =>
              (btn.onclick = (e) => {
                stop(e);
                run(ctx, btn.dataset.action);
              }),
          );
          menu.querySelector("[data-defense-cancel]").onclick = (e) => {
            stop(e);
            menu.remove();
          };
        };
        el.onclick = available.length
          ? defend
          : () => {
              if (!ctx.busy()) showCard(ctx, c, i);
            };
        if (control) control.onclick = defend;
        el.classList.toggle("defense-ready", !!available.length);
        const passed =
          b.reaction.column != null && i % b.columns > b.reaction.column;
        el.classList.toggle("defense-passed", passed);
        el.setAttribute(
          "aria-label",
          cardName(c) +
            (available.length
              ? " · Click to defend"
              : passed
                ? " · Attack has passed this column"
                : " · Cannot defend this hit"),
        );
        if (control)
          control.title = available.length
            ? "Click to absorb this hit. It cannot travel back toward the enemy."
            : passed
              ? "The attack has passed this column."
              : tutorialWaiting
                ? "Follow the highlighted defense for this lesson."
                : "No eligible defense against this hit.";
        const view = document.createElement("button");
        view.className = "defense-view";
        view.textContent = "View";
        view.setAttribute("aria-label", "View " + cardName(c));
        view.onclick = (e) => {
          stop(e);
          if (!ctx.busy()) showCard(ctx, c, i);
        };
        el.append(view);
      });
    }
    const hit = o.battle.reaction,
      node = hit?.lastNode;
    if (hit?.damage > 0 && !node && hit.collapseOrigins?.length) {
      for (const slot of hit.collapseOrigins) {
        const anchor = app.querySelector(`[data-slot="${slot}"]`);
        anchor?.append(attackOrb(5, "Arcane"));
      }
    }
    if (
      hit?.damage > 0 &&
      !hit.statusHit &&
      ["card", "item"].includes(node?.kind)
    ) {
      const anchor =
        node.kind === "card"
          ? app.querySelector(`[data-slot="${node.slot}"]`)
          : app.querySelector(
              `.battle-player .gear-item[data-item-uid="${node.uid}"]`,
            );
      if (anchor) {
        const held = attackOrb(hit.damage, hit.element, hit.finalBlast);
        anchor.append(held);
      }
    }
  }
  enhanceConsumables(ctx);
  if (ctx.frame) {
    app
      .querySelectorAll("button,select,input")
      .forEach((el) => (el.disabled = true));
  }
}

presentation.mjs:
import { bossDestruction, collapseFlight } from "./boss-effects.mjs";
import { stageBounds } from "./stage.mjs";
import {
  spellImpact,
  impactStyles,
  attackOrb,
  statusVisual,
} from "./impact-effects.mjs";
import { installKeywordHelp } from "./keywords.mjs";
import { artPaths } from "./art-paths.mjs";
import { tendrilLash } from "./tendril-effects.mjs";
export function installTooltips() {
  installKeywordHelp();
  const tip = document.createElement("div");
  tip.id = "hover-help";
  tip.setAttribute("role", "tooltip");
  tip.hidden = true;
  document.body.append(tip);
  let timer;
  const hide = () => {
    tip.hidden = true;
    clearTimeout(timer);
  };
  function show(e) {
    const el =
      e.target.closest?.("[data-upgrade-preview]") ||
      e.target.closest?.("[title],[data-tooltip]");
    if (!el) return;
    const value = el.getAttribute("title") || el.dataset.tooltip;
    if (!value) return;
    if (el.hasAttribute("title")) {
      el.dataset.tooltip = value;
      el.removeAttribute("title");
    }
    hide();
    tip.textContent = value;
    tip.hidden = false;
    const r = el.getBoundingClientRect();
    const bounds = stageBounds();
    tip.style.left =
      Math.max(
        bounds.left + 8,
        Math.min(bounds.left + bounds.width - tip.offsetWidth - 8, r.left),
      ) + "px";
    tip.style.top =
      Math.max(
        bounds.top + 8,
        Math.min(
          bounds.top + bounds.height - tip.offsetHeight - 8,
          r.bottom + 8,
        ),
      ) + "px";
    timer = setTimeout(hide, 4000);
  }
  document.addEventListener("pointerover", show);
  document.addEventListener("focusin", show);
  document.addEventListener("pointerout", hide);
  document.addEventListener("focusout", hide);
  document.addEventListener("pointerdown", hide);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") hide();
  });
}
export async function playFrames(before, frames, after, renderView, isFast) {
  const departedOwners = new Set();
  const deferredDeaths = new Set(frames.filter(f => f.kind === "ownerDeath").map(f => f.uid));
  const render = state => {
    if ((!departedOwners.size && !deferredDeaths.size) || !state.battle) return renderView(state);
    const view = structuredClone(state);
    // Observations omit dead enemies. Keep their final portrait mounted until
    // the ordered disappearance sequence has actually played.
    for (const uid of deferredDeaths) {
      if (departedOwners.has(uid) || view.battle.enemies.some(e => e.uid === uid)) continue;
      const portrait = before.battle?.enemies.find(e => e.uid === uid);
      if (portrait) view.battle.enemies.push({ ...structuredClone(portrait), hp: 0 });
    }
    view.battle.enemies = view.battle.enemies.filter(e => !departedOwners.has(e.uid));
    view.battle.ideons = view.battle.ideons.filter(e => !departedOwners.has(e.owner));
    renderView(view);
  };
  if (!frames.length && before.mode === after.mode) return;
  const bar = document.createElement("div");
  bar.className = "presentation-bar";
  bar.innerHTML =
    "<span>Resolving…</span><button data-speed>Fast</button><button data-skip>Skip</button>";
  document.body.append(bar);
  let skip = false,
    fast = false,
    previous = before,
    source = before.battle?.reaction?.source
      ? {
          enemy: before.battle.reaction.source,
          element: before.battle.reaction.element,
        }
      : null;
  bar.querySelector("[data-skip]").onclick = () => (skip = true);
  bar.querySelector("[data-speed]").onclick = () => {
    fast = !fast;
    bar.querySelector("[data-speed]").textContent = fast ? "Normal" : "Fast";
  };
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const ms = (n) =>
    skip
      ? 0
      : fast || isFast()
        ? Math.max(35, n * 0.16)
        : reduced
          ? Math.min(n, 250)
          : n;
  async function pause(n) {
    const deadline = performance.now() + ms(n);
    while (!skip && performance.now() < deadline)
      await new Promise((r) => setTimeout(r, 25));
  }
  const find = (q) => document.querySelector(q);
  const enemy = (uid) => find(`[data-enemy-uid="${uid}"]`);
  const card = (i) => find(`[data-slot="${i}"]`);
  const player = () =>
    find(".battle-player .player-portrait") || find(".player-portrait");
  const item = (uid) =>
    find(`.battle-player .gear-item[data-item-uid="${uid}"]`) ||
    find(`[data-item-detail="${uid}"]`);
  const pathNode = (node) =>
    node?.kind === "enemy"
      ? enemy(node.uid)
      : node?.kind === "card"
        ? card(node.slot)
        : node?.kind === "item"
          ? item(node.uid)
          : ["player","bodyGuard"].includes(node?.kind)
            ? player()
            : null;
  function floating(el, label, cls = "") {
    if (!el) return;
    const r = el.getBoundingClientRect();
    const tag = document.createElement("div");
    tag.className = "impact-number " + cls;
    tag.textContent = label;
    tag.style.left = r.left + r.width / 2 + "px";
    tag.style.top = r.top + r.height / 2 + "px";
    document.body.append(tag);
    return tag;
  }
  async function flash(
    el,
    label,
    dead = false,
    from = null,
    element = null,
    attack = null,
    boost = null,
    revealTarget = true,
    attackVisual = null,
  ) {
    // Reveal the acting/struck foe inside crowded encounters without moving the stage.
    for (const node of revealTarget ? [from, el] : []) {
      if (node?.matches(".enemy")) {
        const panel = node.closest(".enemy-line"),
          r = node.getBoundingClientRect(),
          b = panel?.getBoundingClientRect();
        if (b && (r.top < b.top || r.bottom > b.bottom))
          panel.scrollTop +=
            (r.top < b.top ? r.top - b.top : r.bottom - b.bottom) /
            stageBounds().scale;
      }
    }
    const lash = attackVisual ? await tendrilLash(from, el, attackVisual, {ms, pause, reduced, skip:()=>skip}) : null;
    let projectile;
    if (el && from && from !== el && !reduced && attackVisual !== "tendril" && !skip) {
      const a = (lash?.tip || from).getBoundingClientRect(),
        b = el.getBoundingClientRect();
      projectile = attack
        ? attackOrb(attack.incoming, element, attack.finalBlast)
        : document.createElement("div");
      projectile.classList.add("attack-bolt");
      if (boost) {
        projectile.classList.add("gear-power-sphere");
        projectile.dataset.sourceItem = boost.sourceItem;
        projectile.dataset.targetSlot = boost.slot;
      }
      projectile.dataset.effect = element || "Arcane";
      if (attack) {
        projectile.classList.add("attack-orb-overlay");
        projectile.style.setProperty("--orb-scale", stageBounds().scale);
      }
      projectile.style.setProperty(
        "--hit-color",
        (impactStyles[element] || impactStyles.Arcane).color,
      );
      document.body.append(projectile);
      const animation = projectile.animate(
        [
          {
            left: a.left + a.width / 2 + "px",
            top: a.top + a.height / 2 + "px",
            opacity: 1,
          },
          {
            left: b.left + b.width / 2 + "px",
            top: b.top + b.height / 2 + "px",
            opacity: 1,
          },
        ],
        { duration: ms(350), fill: "forwards", easing: "ease-in" },
      );
      await Promise.race([animation.finished, pause(350)]);
      projectile.remove();
    }
    if (skip) { lash?.node.remove(); return; }
    // Arrive in the same paint as the hit burst, before its pause or disintegration.
    // A viewport overlay stays visible even while the struck card fades underneath.
    if (el && attack?.remaining > 0) {
      const r = el.getBoundingClientRect();
      const orb = attackOrb(attack.remaining, element, attack.finalBlast);
      orb.classList.add("attack-orb-overlay");
      orb.style.left = r.left + r.width / 2 + "px";
      orb.style.top = r.top + r.height / 2 + "px";
      orb.style.setProperty("--orb-scale", stageBounds().scale);
      document.body.append(orb);
    }
    const burst = element
      ? spellImpact(el, element, { duration: ms(500), reduced, finalBlast: attack?.finalBlast })
      : null;
    el?.classList.add("impact");
    const tag = floating(el, label, attack ? "attack-impact-number" : "");
    if (tag && Object.values(statusVisual).includes(element)) {
      tag.classList.add("status-impact-number");
      tag.style.top = parseFloat(tag.style.top) - 55 + "px";
    }
    await Promise.all([pause(550), lash?.retract()]);
    el?.classList.remove("impact");
    tag?.remove();
    burst?.remove();
    if (skip) return;
    if (dead && el) {
      el.classList.add("disintegrating");
      await pause(600);
    }
  }
  try {
    render(before);
    for (let frameIndex = 0; frameIndex < frames.length; frameIndex++) {
      const frame = frames[frameIndex];
      if (skip) break;
      bar.querySelector("span").textContent =
        frame.kind === "move"
          ? "Movement"
          : frame.name ||
            {
              incoming: "Incoming attack",
              hit: "Damage",
              defend: "Defense",
              activate: "Activation",
            }[frame.kind] ||
            "Resolving";
      if (frame.parallelGroup != null) {
        // Damage still resolves in engine order. Animate different targets together,
        // keeping each target's follow-up Ring hit/status in its original order.
        const batch = [frame];
        while (frames[frameIndex + 1]?.parallelGroup === frame.parallelGroup)
          batch.push(frames[++frameIndex]);
        const lanes = new Map();
        for (const hit of batch) {
          if (!lanes.has(hit.uid)) lanes.set(hit.uid, []);
          lanes.get(hit.uid).push(hit);
        }
        await Promise.all(
          [...lanes.values()].map(async (hits) => {
            for (const hit of hits) {
              if (skip) break;
              const from =
                hit.sourceItem != null
                  ? item(hit.sourceItem) || player()
                  : card(hit.sourceSlot);
              if (hit.sourceItem != null) from?.classList.add("gear-proc");
              try {
                await flash(
                  enemy(hit.uid),
                  hit.kind === "status" ? hit.name : "−" + hit.amount,
                  hit.dead && !deferredDeaths.has(hit.uid),
                  from,
                  hit.kind === "status"
                    ? statusVisual[hit.statusEffect]
                    : hit.element,
                  null,
                  null,
                  false,
                );
              } finally {
                if (hit.sourceItem != null) from?.classList.remove("gear-proc");
              }
            }
          }),
        );
        // Keep all targets mounted until every projectile, hit and death finishes.
        previous = batch.at(-1).state;
        render(previous);
        continue;
      } else if (frame.kind === "reveal") {
        const masked = structuredClone(frame.state);
        if (!frame.incremental) masked.battle.phase = "start";
        masked.battle.insight =
          frame.insight ??
          masked.battle.revealInsight ??
          masked.battle.hand.length;
        render(masked);
        const hand = [
          ...document.querySelectorAll(".revealed-hand [data-hand]"),
        ].filter(
          (el) =>
            !frame.incremental || frame.cards.includes(Number(el.dataset.hand)),
        );
        for (const el of hand) {
          el.classList.remove("unavailable");
          el.classList.add("deal-card", "face-down");
          el.style.visibility = "hidden";
          el.removeAttribute("title");
          el.removeAttribute("data-tooltip");
          el.setAttribute("aria-label", "Face-down card");
          const back = document.createElement("div");
          back.className = "reveal-back";
          back.setAttribute("aria-hidden", "true");
          back.innerHTML = `<svg class="druid-seal" viewBox="0 0 100 100" aria-hidden="true">
            <circle cx="50" cy="50" r="43" fill="none" stroke="currentColor" stroke-width="1"/>
            <circle cx="50" cy="50" r="37" fill="none" stroke="currentColor" stroke-width=".5" stroke-dasharray="2 5"/>
            <g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="M50 76V25 M50 52L32 38V27 M50 52L68 38V27 M50 65L25 52V40 M50 65L75 52V40 M50 74L35 83 M50 74L65 83 M50 74V87"/>
              <path d="M32 38L21 33 M68 38L79 33 M25 52L17 48 M75 52L83 48"/>
            </g>
            <g fill="currentColor">
              <path d="M50 34C36 27 42 17 50 12C58 17 64 27 50 34Z M32 32C20 29 22 20 25 16C33 17 39 24 32 32Z M68 32C80 29 78 20 75 16C67 17 61 24 68 32Z M25 48C13 45 14 37 17 33C25 34 31 40 25 48Z M75 48C87 45 86 37 83 33C75 34 69 40 75 48Z"/>
            </g>
          </svg>`;
          el.append(back);
        }
        // Overlap neighboring animations while exposing card faces in draw order.
        async function animateCard(el, keyframes, duration, easing) {
          const animation = el.animate(keyframes, {
            duration: ms(duration),
            fill: "forwards",
            easing,
          });
          try {
            await pause(duration);
          } finally {
            animation.cancel();
          }
        }
        const deals = [];
        for (let i = 0; i < hand.length && !skip; i++) {
          const el = hand[i];
          el.style.visibility = "visible";
          deals.push(
            animateCard(
              el,
              [
                {
                  opacity: 0,
                  transform: reduced ? "none" : "translateY(20px)",
                },
                { opacity: 1, transform: "none" },
              ],
              120,
              "ease-out",
            ),
          );
          if (i < hand.length - 1) await pause(70);
        }
        await Promise.all(deals);
        await pause(100);
        const opens = [];
        for (let i = 0; i < hand.length && !skip; i++) {
          const el = hand[i];
          if (!reduced)
            await animateCard(
              el,
              [
                { transform: "perspective(700px) rotateY(0deg)" },
                { transform: "perspective(700px) rotateY(90deg)" },
              ],
              140,
              "ease-in",
            );
          const counter = find(".resources > span:first-child");
          const remaining =
            i === hand.length - 1
              ? 0
              : Math.max(0, masked.battle.insight - i - 1);
          if (counter) {
            counter.querySelector("b").textContent = remaining;
            counter.classList.toggle("depleted", remaining === 0);
          }
          el.classList.remove("face-down");
          el.removeAttribute("aria-label");
          if (!reduced)
            opens.push(
              animateCard(
                el,
                [
                  { transform: "perspective(700px) rotateY(-90deg)" },
                  { transform: "perspective(700px) rotateY(0deg)" },
                ],
                140,
                "ease-out",
              ),
            );
          if (i < hand.length - 1) await pause(reduced ? 200 : 60);
        }
        await Promise.all(opens);
        await pause(300);
        if (!skip) render(frame.state);
      } else if (frame.kind === "gridDestruction") {
        await bossDestruction(frame, {
          card,
          player,
          enemy,
          ms,
          pause,
          reduced,
          skip: () => skip,
        });
        render(frame.state);
      } else if (frame.kind === "bileMove") {
        await flash(
          frame.to === "player" ? player() : card(frame.to),
          "Bile",
          false,
          frame.from == null ? enemy(frame.source) : card(frame.from),
          "Poison",
        );
        render(frame.state);
      } else if (frame.kind === "phaseShift") {
        const ghosts = [];
        for (const m of frame.moves) {
          const a = card(m.from),
            z = card(m.to);
          if (!a || !z) continue;
          const ar = a.getBoundingClientRect(),
            zr = z.getBoundingClientRect();
          const ghost = a.cloneNode(true);
          ghost.className += " phase-moving-card";
          ghost
            .querySelectorAll(
              ".corruption-card,.corruption-seal,.corruption-foretell,.bile-motion,.bile-forecast,.phase-label,.mending-ribbon,.mending-target-ring,.nausea-aura,.corruption-cover-aura",
            )
            .forEach((el) => el.remove());
          for (const cls of [...ghost.classList])
            if (
              cls.startsWith("corruption") ||
              [
                "corrupted",
                "has-bile",
                "nausea-affected",
                "anger-affected",
                "bile-destination",
                "phase-warning",
              ].includes(cls)
            )
              ghost.classList.remove(cls);
          Object.assign(ghost.style, {
            position: "fixed",
            left: ar.left + "px",
            top: ar.top + "px",
            width: ar.width + "px",
            height: ar.height + "px",
            margin: "0",
            zIndex: "9999",
            pointerEvents: "none",
          });
          document.body.append(ghost);
          const end = {
            transform: reduced
              ? "none"
              : `translate(${zr.left - ar.left}px,${zr.top - ar.top}px)`,
            opacity: 1,
          };
          let keys = [{ transform: "translate(0,0)", opacity: 1 }, end];
          if (!reduced && m.to < m.from) {
            const rect = find(".mind").getBoundingClientRect();
            const horizontal = frame.axis === "H";
            keys = [
              keys[0],
              {
                transform: horizontal
                  ? `translate(${rect.right - ar.left}px,0)`
                  : `translate(0,${rect.bottom - ar.top}px)`,
                opacity: 0,
                offset: 0.49,
              },
              {
                transform: horizontal
                  ? `translate(${rect.left - ar.left - ar.width}px,0)`
                  : `translate(0,${rect.top - ar.top - ar.height}px)`,
                opacity: 0,
                offset: 0.5,
              },
              end,
            ];
          }
          const anim = ghost.animate(keys, {
            duration: ms(650),
            fill: "forwards",
            easing: "ease-in-out",
          });
          ghosts.push({ ghost, anim });
        }
        await pause(700);
        for (const { ghost, anim } of ghosts) {
          anim.cancel();
          ghost.remove();
        }
        render(frame.state);
      } else if (frame.kind === "eggHatch") {
        const target = card(frame.slot);
        const burst = spellImpact(target, frame.element || "Arcane", { duration: ms(650), reduced });
        burst?.classList.add("egg-hatching");
        await pause(300);
        if (frame.covered && target) {
          if (frame.destroyed?.length) target.classList.add("disintegrating");
          await flash(target, "To " + (frame.destination || "Discard"), false, null, frame.element);
        }
        burst?.remove();
        render(frame.state);
      } else if (frame.kind === "mineExplosion") {
        const target = card(frame.slot);
        const burst = spellImpact(target, "Fire", {
          duration: ms(750),
          reduced,
        });
        burst?.classList.add("mine-explosion");
        if (burst) burst.dataset.slot = String(frame.slot);
        target?.classList.add("mine-detonating");
        await pause(500);
        if (frame.covered) {
          target?.classList.add("disintegrating");
          await pause(350);
        }
        burst?.remove();
        render(frame.state);
      } else if (frame.kind === "corruption") {
        render(frame.state);
        const targets = (frame.slots || [frame.slot]).map(card).filter(Boolean);
        targets.forEach((target) => target.classList.add("corruption-flare"));
        await pause(650);
        targets.forEach((target) =>
          target.classList.remove("corruption-flare"),
        );
      } else if (frame.kind === "resources") {
        render(frame.state);
        await pause(220);
      } else if (frame.kind === "status") {
        // Battle-start curses need the battlefield and equipped icons before Reveal.
        if (frame.state.mode === "battle" && !find(".battle-player"))
          render(frame.state);
        const target =
          frame.target === "player"
            ? player()
            : frame.target === "card"
              ? card(frame.slot)
              : enemy(frame.uid);
        const from =
          frame.gridSourceSlot != null
            ? card(frame.gridSourceSlot)
            : frame.sourceItem != null
              ? item(frame.sourceItem)
              : frame.source != null
                ? enemy(frame.source)
                : frame.sourceSlot != null
                  ? card(frame.sourceSlot)
                  : null;
        if (frame.sourceItem != null) from?.classList.add("gear-proc");
        try {
          await flash(
            target,
            frame.name,
            false,
            from,
            statusVisual[frame.statusEffect] || null,
          );
        } finally {
          from?.classList.remove("gear-proc");
        }
        render(frame.state);
      } else if (frame.kind === "move") {
        if (!find(".field")) {
          const initial = structuredClone(frame.state);
          initial.mode = "field";
          if (frame.player) Object.assign(initial.field, frame.from);
          else {
            const e = initial.field.entities.find((e) => e.uid === frame.uid);
            if (e) Object.assign(e, frame.from);
          }
          render(initial);
        }
        let token = frame.player
          ? find("[data-player-token]")
          : find(`[data-token="${frame.uid}"]`);
        const start = find(`[data-cell="${frame.from.y * (frame.state.field.size || 11) + frame.from.x}"]`),
          end = find(`[data-cell="${frame.to.y * (frame.state.field.size || 11) + frame.to.x}"]`);
        if (!token && start && frame.enemy) {
          token = document.createElement("img");
          token.src =
            artPaths["enemy-" + frame.enemy] ||
            "assets/enemy-" + frame.enemy + ".png";
          token.className = "moving-ghost";
          start.append(token);
        }
        if (token && start && end) {
          const a = start.getBoundingClientRect(),
            b = end.getBoundingClientRect();
          token.style.zIndex = "8";
          const animation = token.animate(
            [
              { transform: "translate(0,0)" },
              {
                transform: `translate(${(b.left - a.left) / stageBounds().scale}px,${(b.top - a.top) / stageBounds().scale}px)`,
              },
            ],
            { duration: ms(280), fill: "forwards", easing: "ease-in-out" },
          );
          await Promise.race([animation.finished, pause(280)]);
        } else await pause(220);
        render(frame.state);
        if (
          frame.to.x === frame.state.field.x &&
          frame.to.y === frame.state.field.y &&
          !frame.player
        ) {
          const cell = find(`[data-cell="${frame.to.y * (frame.state.field.size || 11) + frame.to.x}"]`);
          cell?.classList.add("collision");
          await pause(550);
        }
      } else if (frame.kind === "shieldBoost") {
        const from = item(frame.sourceItem);
        from?.classList.add("gear-proc");
        try {
          await flash(
            card(frame.slot),
            "+" + frame.amount + " Guard",
            false,
            from,
            frame.element === "Arcane" ? "Light" : frame.element,
            null,
            frame,
          );
        } finally {
          from?.classList.remove("gear-proc");
        }
        render(frame.state);
      } else if (frame.kind === "consume") {
        source = { item: frame.uid };
        await flash(
          find('[data-consumable-uid="' + frame.uid + '"]') || player(),
          frame.name,
          false,
          null,
          "Light",
        );
        if (frame.healed)
          await flash(
            player(),
            "+" + frame.healed + " HP",
            false,
            null,
            "Earth",
          );
        else if (frame.focus || frame.channel)
          await flash(
            find(".resources"),
            "+" +
              (frame.focus || frame.channel) +
              (frame.focus ? " Focus" : " Channel"),
          );
        render(frame.state);
      } else if (frame.kind === "ideonVolley") {
        render(frame.state);
        await Promise.all(frame.bullets.map(e => flash(enemy(e.uid), e.name, false, null, e.element)));
      } else if (frame.kind === "ideonSpawn") {
        render(frame.state);
        await flash(enemy(frame.uid), frame.name, false, null, frame.element);
      } else if (frame.kind === "ideonTravel") {
        let fromSlot = frame.fromSlot;
        // These are presentation-only stops: do not resolve fields or collisions
        // on intermediate spaces, or turn a two-space command into two commands.
        for (const slot of frame.path) {
          const from = card(fromSlot)?.getBoundingClientRect();
          const view = structuredClone(frame.state);
          view.battle.ideons = view.battle.ideons.filter(e => e.uid !== frame.uid);
          view.battle.ideons.push({ ...frame.projectile, slot });
          render(view);
          const el = enemy(frame.uid), to = el?.getBoundingClientRect();
          if (el && from && to && !reduced) {
            await el.animate([
              { transform: `translate(${from.left + from.width / 2 - to.left - to.width / 2}px,${from.top + from.height / 2 - to.top - to.height / 2}px)` },
              { transform: "translate(0,0)" },
            ], { duration: ms(210), easing: "ease-in-out" }).finished;
          } else await pause(100);
          fromSlot = slot;
          await pause(45);
        }
        if (frame.exiting) await flash(enemy(frame.uid), "", true);
        render(frame.state);
      } else if (frame.kind === "ideonMove" || frame.kind === "guideMove") {
        const from = card(frame.fromSlot)?.getBoundingClientRect();
        render(frame.state);
        const el =
            frame.kind === "guideMove" ? card(frame.slot) : enemy(frame.uid),
          to = el?.getBoundingClientRect();
        if (frame.kind === "guideMove")
          source = { slot: frame.slot, element: "Arcane" };
        if (el && from && to && !reduced) {
          const animation = el.animate(
            [
              {
                transform: `translate(${from.left + from.width / 2 - to.left - to.width / 2}px,${from.top + from.height / 2 - to.top - to.height / 2}px)`,
              },
              { transform: "translate(0,0)" },
            ],
            { duration: ms(420), easing: "ease-in-out" },
          );
          await animation.finished;
        } else await pause(120);
      } else if (frame.kind === "activate") {
        source = { slot: frame.slot };
        await flash(card(frame.slot), frame.name);
        render(frame.state);
      } else if (frame.kind === "hiveDeath" || frame.kind === "ownerDeath") {
        if (frame.kind === "ownerDeath") {
          const scene = structuredClone(frame.state);
          scene.battle.ideons.push(...frame.children);
          render(scene);
        }
        await flash(enemy(frame.uid), "", true);
        enemy(frame.uid)?.remove();
        const children = frame.insects || frame.children.map(e => e.uid);
        await Promise.all(children.map(uid => flash(enemy(uid), "", true)));
        departedOwners.add(frame.uid);
        const cleared = structuredClone(frame.state);
        cleared.battle.enemies = cleared.battle.enemies.filter(e => e.hp > 0);
        render(cleared);
        bar.querySelector("span").textContent = frame.kind === "hiveDeath" ? "The Mind Hive falls silent" : `${frame.name} falls`;
        bar.dataset.stage = frame.kind === "hiveDeath" ? "hive-cleared" : "owner-cleared";
        // One real second to see the defeated owner and its Ideons gone.
        const until = performance.now() + 1000;
        while (!skip && performance.now() < until)
          await new Promise(resolve => setTimeout(resolve, 25));
      } else if (frame.kind === "death") {
        await flash(enemy(frame.uid), frame.name, true);
        render(frame.state);
      } else if (frame.kind === "incoming") {
        source =
          frame.gridSourceSlot != null
            ? { slot: frame.gridSourceSlot, element: frame.element }
            : { enemy: frame.source, element: frame.element };
        const el =
          frame.gridSourceSlot != null
            ? card(frame.gridSourceSlot)
            : frame.collapseOrigins
              ? null
              : enemy(frame.source);
        await flash(
          el,
          `${frame.name} · ${frame.amount} ${frame.element || ""}`,
          false, null, frame.finalBlast ? frame.element : null,
          frame.finalBlast ? { finalBlast: true } : null,
        );
        render(frame.state);
      } else if (frame.kind === "hit" || frame.kind === "defend") {
        if (frame.attackPath)
          document
            .querySelectorAll(".held-attack")
            .forEach((el) => el.remove());
        const el = frame.attackPath
          ? pathNode(frame.pathTo)
          : frame.target === "enemy"
            ? enemy(frame.uid)
            : frame.target === "player"
              ? player()
              : frame.slot != null
                ? card(frame.slot)
                : frame.item
                  ? find(`[data-item-detail="${frame.item}"]`)
                  : player();
        const from = frame.statusTick
          ? null
          : frame.attackPath
            ? pathNode(frame.pathFrom)
            : frame.sourceItem != null
              ? find(
                  `[data-consumable-uid="${frame.sourceItem}"], .battle-player .gear-item[data-item-uid="${frame.sourceItem}"]`,
                ) || player()
              : frame.gridSourceSlot != null
                ? card(frame.gridSourceSlot)
                : source?.slot != null
                  ? card(source.slot)
                  : source?.enemy
                    ? enemy(source.enemy)
                    : null;
        if (frame.armor)
          find(`[data-item-detail="${frame.armor}"]`)?.classList.add(
            "defense-ready",
          );
        if (frame.sourceItem != null) from?.classList.add("gear-proc");
        try {
          if (frame.collapseOrigins?.length)
            await collapseFlight(frame.collapseOrigins, el, {
              card,
              ms,
              pause,
              reduced,
              skip: () => skip,
            });
          await flash(
            el,
            frame.loss != null
              ? "−" + frame.loss
              : frame.amount != null
                ? (frame.kind === "defend" ? "Absorbed " : "−") + frame.amount
                : frame.name || "Hit",
            frame.dead && !deferredDeaths.has(frame.uid),
            frame.collapseOrigins?.length ? null : from,
            frame.amount != null
              ? statusVisual[frame.attackStatus] ||
                  statusVisual[frame.statusTick] ||
                  frame.element ||
                  source?.element ||
                  "Arcane"
              : null,
            frame.attackPath && frame.pathFrom
              ? {
                  incoming: previous.battle?.reaction?.damage ?? frame.amount,
                  finalBlast: frame.finalBlast,
                  remaining: ["card", "item"].includes(frame.pathTo?.kind)
                    ? frame.remaining
                    : 0,
                }
              : null,
            null,
            true,
            frame.attackVisual,
          );
        } finally {
          if (frame.sourceItem != null) from?.classList.remove("gear-proc");
        }
        render(frame.state);
        // Swap the impact overlay for the rendered waiting marker without a blank frame.
        document
          .querySelectorAll(".attack-orb-overlay")
          .forEach((el) => el.remove());
      } else render(frame.state);
      previous = frame.state;
    }
    if (!skip && before.mode !== after.mode) {
      bar.querySelector("span").textContent =
        after.mode === "battle"
          ? "Encounter"
          : after.mode === "reward"
            ? "Victory"
            : after.mode === "result"
              ? after.outcome === "loss"
                ? "You Died"
                : after.tutorial
                  ? after.tutorial.name + " Complete"
                  : "Stratum " + (after.stratum || 1) + " Complete"
              : "Continue";
      if (!frames.some(f => f.kind === "hiveDeath" || f.kind === "ownerDeath"))
        await pause(after.mode === "reward" ? 700 : 450);
    }
  } finally {
    bar.remove();
    document
      .querySelectorAll(
        ".impact-number,.attack-bolt,.spell-impact,.attack-orb-overlay,.boss-effect,.tendril-effect",
      )
      .forEach((el) => el.remove());
  }
}

