import {items,cards,ELEMENTS} from './content.mjs';
import {adjacent,cardEffects,hasDirectDamageActivation,attunementSourceElement} from './engine.mjs';
import {canEnter,retargetCoveredCorruptions} from './corruptions.mjs';
import {ideonsAt,coveredByIdeon} from './ideons.mjs';
const top=s=>s?.at(-1);
export const suppliesAvailable=(s,id)=>items[id]?.expansion!=='supplies'||(items[id].stratum||1)<=(s.stratum||1);
export function supplyChoices(g,item,add) {
  const b=g.s.battle,f=items[item.id].consumable;
  if(!items[item.id].expansion)return false;
  const emit=(p={},suffix='')=>add('consume','Use '+items[item.id].name+suffix,{uid:item.uid,...p},{...f,consumable:true},{channel:0});
  if(f.tincture) b.grid.forEach((s,i)=>{if(top(s)&&!coveredByIdeon(b,i)) for(const el of f.tincture==='choose'?ELEMENTS:[f.tincture]) if(top(s).element!==el)emit({slot:i,element:el},` → ${cards[top(s).id].name} (${i+1}) · ${el}`);});
  else if(f.shift)b.grid.forEach((s,i)=>{if(!top(s)||coveredByIdeon(b,i)||s.some(c=>c.lock||c.mending))return;for(const j of adjacent(i))if(!b.grid[j].length&&!ideonsAt(b,j).length&&canEnter(b,top(s),j))emit({slot:i,destination:j},` · ${i+1} → ${j+1}`);});
  else if(f.recall)b.grid.forEach((s,i)=>{if(g.recallCost(s)!=null)emit({slot:i},` → ${cards[top(s).id].name} (${i+1})`);});
  else if(f.memory)for(const c of b.discard)emit({card:c.uid},' → '+cards[c.id].name);
  else if(f.inspiration==='choose')for(const c of b.deck)emit({card:c.uid},' → '+cards[c.id].name);
  else if(f.inspiration){if(b.deck.length)emit();}
  else if(f.cleanse){if(g.s.status[f.cleanse]>0)emit();}
  else if(!(f.fury&&b.fury)&&!(f.bastion&&b.bastion)&&!(f.confluence&&b.confluence))emit();
  return true;
}
export function recallSupply(g,i) {
  const b=g.s.battle;
  b.discard.push(...b.grid[i].map(c=>({uid:c.uid,id:c.id,upgrade:c.upgrade})));
  b.grid[i]=[]; b.shields=b.shields.filter(x=>x.slot!==i);
  b.recallCount=Math.min(2,(b.recallCount||0)+1);
  g.present('recall',{slot:i,name:'Recall Mist'});
}
export function useSupply(g,f,a) {
  const s=g.s,b=s.battle;
  if(f.tincture){const c=top(b.grid[a.slot]); c.element=a.element;c.transmuted=true;(b.tinctures||={})[c.uid]=a.element;
    for(const shield of b.shields.filter(x=>x.owner===c.uid))shield.element=a.element;}
  if(f.shift){b.grid[a.destination]=b.grid[a.slot];b.grid[a.slot]=[];for(const sh of b.shields)if(sh.slot===a.slot)sh.slot=a.destination;g.present('guideMove',{fromSlot:a.slot,slot:a.destination,name:'Shifting Sap'});retargetCoveredCorruptions(g,[a.destination]);}
  if(f.recall)recallSupply(g,a.slot);
  if(f.memory){const c=b.discard.find(c=>c.uid===a.card);b.discard=b.discard.filter(x=>x.uid!==a.card);b.deck.unshift(c);b.drawTop=[c.uid,...(b.drawTop||[]).filter(uid=>uid!==c.uid)];}
  if(f.cleanse)s.status[f.cleanse]=0;
  if(f.immunity)b.statusProtection=b.turn+1;
  if(f.fury)b.fury=true;
  if(f.bastion)b.bastion=true;
  if(f.confluence)b.confluence=true;
  if(f.inspiration){
    const idx=f.inspiration==='choose'?b.deck.findIndex(c=>c.uid===a.card):nextDrawIndex(g);
    const c=b.deck.splice(idx,1)[0]; b.hand.push(c);b.revealedCount=(b.revealedCount||0)+1;
    b.inspiration={uid:c.uid,stage:'place',phase:b.phase,destroy:f.inspiration==='choose'}; b.phase='place';
    g.present('reveal',{name:'Inspiration',cards:[c.uid],insight:1,incremental:true});
  }
}
export function nextDrawIndex(g){
  const b=g.s.battle;
  while(b.drawTop?.length){const uid=b.drawTop.shift(),i=b.deck.findIndex(c=>c.uid===uid);if(i>=0)return i;}
  return Math.floor(g.rand()*b.deck.length);
}
// Authoritative ordinary legality, projected with only the two waived costs.
export function inspirationLegal(g){
  const b=g.s.battle,p=b.inspiration;
  const old={phase:b.phase,focus:b.focus,channel:b.channel,hand:b.hand};
  g.projectingSupply=true;b.phase=p.stage;b.focus=999;b.channel=999;
  if(p.stage==='place')b.hand=b.hand.filter(c=>c.uid===p.uid);
  let legal;
  try{legal=g.baseLegal();}finally{Object.assign(b,old);g.projectingSupply=false;}
  const slot=b.grid.findIndex(s=>top(s)?.uid===p.uid);
  const choices=legal.filter(a=>p.stage==='place'?['place','placeStrike'].includes(a.type)&&a.uid===p.uid&&(a.slot==null||!b.grid[a.slot].length):a.type==='activate'&&a.slot===slot&&(a.focusSpend||0)<=old.focus&&(a.costs.focus||0)<=old.focus);
  return choices.length?choices.map(a=>({...a,label:'Inspiration · '+a.label,costs:{...a.costs,focus:0,channel:0},effects:{...a.effects,inspiration:true}})):
    [{type:'inspirationKeep',key:JSON.stringify(['inspirationKeep',{}]),label:'Cannot resolve: keep revealed card in hand',effects:{},costs:{}}];
}
export function finishInspiration(g,a){
  const b=g.s.battle,p=b?.inspiration;if(!p)return;
  if(a.type==='consume')return;
  if(p.stage==='place'&&a.type==='place'){
    const slot=b.grid.findIndex(s=>top(s)?.uid===p.uid);
    if(slot>=0){p.stage='activate';b.phase='activate';return;}
  }
  if(a.type==='activate'||a.type==='inspirationKeep'){
    const i=b.grid.findIndex(s=>s.some(c=>c.uid===p.uid));
    if(i>=0){
      const c=b.grid[i].find(c=>c.uid===p.uid);
      if(a.type==='inspirationKeep') {b.hand.push({uid:c.uid,id:c.id,upgrade:c.upgrade});b.grid[i]=b.grid[i].filter(x=>x.uid!==c.uid);}
      else if(p.destroy||g.recallCost([c])==null)g.destroyCard(i,c.uid);
      else {b.discard.push({uid:c.uid,id:c.id,upgrade:c.upgrade});b.grid[i]=b.grid[i].filter(x=>x.uid!==c.uid);}
      b.shields=b.shields.filter(x=>x.owner!==p.uid);
    }
  }
  b.phase=p.phase;delete b.inspiration;
}
export function supplyResourceLegal(g){
  const b=g.s.battle,total=b.focus+b.channel,old={focus:b.focus,channel:b.channel};
  g.projectingSupply=true;b.focus=total;b.channel=total;
  let actions;try{actions=g.baseLegal();}finally{Object.assign(b,old);g.projectingSupply=false;}
  return actions.filter(a=>(a.costs.focus||0)+(a.costs.channel||0)<=total);
}
export function prepareSupplyPayment(g,a){
  const b=g.s.battle;if(!b||g.s.mode!=='battle'||!b.confluence||b.inspiration)return;
  const f=a.costs.focus||0,c=a.costs.channel||0;
  if(b.focus<f){const n=f-b.focus;b.focus+=n;b.channel-=n;}
  if(b.channel<c){const n=c-b.channel;b.channel+=n;b.focus-=n;}
}
export function equipmentStart(g){
  const b=g.s.battle;b.recallCount=0;b.remembranceGained=0;b.echoPrevious=null;b.echoUsed={};b.resonanceUsed={};b.prismaticChoices={};
  b.resonanceHelms=g.equipped().filter(x=>x.definition.id==='resonanceHelm').map(x=>x.uid);
  b.lastStandActive=g.s.hp<=g.s.maxHp/3;
}
export function supplyPreview(b,c,i,element=c.element){
  const f=cardEffects(c),charged=!cards[c.id].charge||c.charge>=cards[c.id].charge;
  const damage=charged&&hasDirectDamageActivation(c),guard=charged&&!!(f.shield||f.ward);
  const chain=(cards[c.id].attune||f.conduit)&&element!=='Arcane'&&adjacent(i).some(j=>{const n=top(b.grid[j]);return n&&n.lastActivatedTurn===b.turn&&attunementSourceElement(b,n)===element;});
  const bonus=chain?4*(b.resonanceHelms||[]).filter(uid=>!b.resonanceUsed?.[uid]).length:0;
  return {damageBonus:damage?bonus:0,guardBonus:!damage&&guard?bonus:0,damageMultiplier:damage&&b.fury?2:1,guardMultiplier:guard&&b.bastion?2:1};
}
export function equipmentEnd(g){
  const b=g.s.battle,old=b.bracelets||[];
  b.bracelets=g.equipped().filter(x=>x.definition.effect.block).map(x=>{
    const prev=old.find(y=>y.uid===x.uid);let block=x.definition.effect.block;
    if(x.id==='reservoirBracelet'||x.definition.id==='reservoirBracelet')block=Math.min(12,(prev?.block??0)+(b.turn<=1&&!prev?4:4));
    if(x.definition.id==='reclaimerBracelet')block=3+3*(b.recallCount||0);
    if(x.definition.id==='lastStandBracelet'&&b.lastStandActive)block=9;
    return {uid:x.uid,block,element:b.prismaticChoices?.[x.uid]||x.element,name:x.definition.name};
  });
  delete b.confluence;
}
export function gearChoices(g,add){
  const b=g.s.battle;if(g.s.mode!=='battle'||b.reaction||!['place','activate'].includes(b.phase))return;
  for(const x of g.equipped())if(x.definition.id==='prismaticBracelet'&&!b.prismaticChoices?.[x.uid])for(const element of ELEMENTS)
    add('braceletElement','Prismatic Bracelet · '+element,{uid:x.uid,element},{element},{});
}
export function destructionGuard(g,count){
  const b=g.s.battle;if(!g.equipped().some(x=>x.definition.id==='remembranceArmor'))return;
  const gain=Math.min(8-(b.remembranceGained||0),count*2);b.remembranceGained=(b.remembranceGained||0)+gain;b.bodyGuard=(b.bodyGuard||0)+gain;
}
export function activationSupply(g,c,i,element){
  const b=g.s.battle,f=cardEffects(c),charging=cards[c.id].charge&&c.charge<cards[c.id].charge;
  const damaging=hasDirectDamageActivation(c)&&!charging;
  const guard=!!(f.shield||f.ward)&&!charging;
  const linked=(cards[c.id].attune||f.conduit)&&element&&element!=='Arcane'&&adjacent(i).some(j=>{const n=top(b.grid[j]);return n&&n.lastActivatedTurn===b.turn&&attunementSourceElement(b,n)===element;});
  let bonus=0;
  if(linked&&(damaging||guard))for(const x of g.equipped())if(x.definition.id==='resonanceHelm'&&!b.resonanceUsed?.[x.uid]){(b.resonanceUsed||={})[x.uid]=true;bonus+=4;g.present('shieldBoost',{sourceItem:x.uid,slot:i,amount:4,element,name:x.definition.name});}
  const result={damageMultiplier:damaging&&b.fury?2:1,guardMultiplier:guard&&b.bastion?2:1,damageBonus:damaging?bonus:0,guardBonus:!damaging&&guard?bonus:0};
  if(damaging)delete b.fury;if(guard)delete b.bastion;
  return result;
}
export function echoAttack(g,c,i,element,target){
  const b=g.s.battle;if(!hasDirectDamageActivation(c))return;
  if(b.echoPrevious&&b.echoPrevious!==element&&target?.hp>0)for(const gear of g.equipped())if(gear.definition.id==='echoRing'&&!b.echoUsed?.[gear.uid]){
    (b.echoUsed||={})[gear.uid]=true;g.damageEnemy(target,5,element,{card:c.uid},gear.uid);
  }
  b.echoPrevious=element;
}

tendril-effects.mjs:
// A tapered, curling limb. Viewport coordinates match the other attack overlays.
export async function tendrilLash(from, target, kind, api) {
  if (!from || !target || api.skip()) return null;
  const a=from.getBoundingClientRect(), b=target.getBoundingClientRect();
  const x=a.left+a.width/2, y=a.top+a.height/2;
  const dx=b.left+b.width/2-x, dy=b.top+b.height/2-y;
  const distance=Math.hypot(dx,dy);
  if (!distance) return null;
  const reach=kind==='splash'?Math.min(distance*.35,85):distance;
  const node=document.createElement('div');
  node.className='tendril-effect';node.dataset.attack=kind;
  node.setAttribute('aria-hidden','true');
  node.style.cssText=`left:${x}px;top:${y-60}px;width:${reach+12}px;height:120px;transform:rotate(${Math.atan2(dy,dx)}rad)`;
  const spine=`M 0 60 C ${reach*.24} 19 ${reach*.56} 95 ${reach} 60`;
  const body=`${spine} C ${reach*.58} 106 ${reach*.23} 40 0 74 Z`;
  node.innerHTML=`<svg viewBox="0 0 ${reach+12} 120" aria-hidden="true"><g class="tendril-limb"><path class="tendril-flesh" d="${body}"/><path class="tendril-nerve" d="${spine}"/><path class="tendril-glimmer" d="${spine}"/></g></svg>`;
  document.body.append(node);
  const limb=node.querySelector('g');
  const extension=limb.animate(api.reduced
    ? [{opacity:0},{opacity:1}]
    : [{transform:'scaleX(.08)',opacity:.3},{transform:'scaleX(1.04)',opacity:1,offset:.8},{transform:'scaleX(1)',opacity:1}],
    {duration:api.ms(300),fill:'forwards',easing:'ease-out'});
  await Promise.race([extension.finished,api.pause(300)]);
  // Retain contact through the impact; the caller retracts alongside the burst.
  return {
    node,
    tip: { getBoundingClientRect:()=>({left:x+dx/distance*reach,top:y+dy/distance*reach,width:0,height:0}) },
    retract: async()=>{
      const motion=limb.animate(api.reduced?[{opacity:1},{opacity:0}]:[{transform:'scaleX(1)',opacity:1},{transform:'scaleX(.08)',opacity:0}],
        {duration:api.ms(240),fill:'forwards',easing:'ease-in'});
      await Promise.race([motion.finished,api.pause(240)]);
      motion.cancel();extension.cancel();node.remove();
    },
  };
}

trade-ui.mjs:
import { cards, items, cardText } from "./content.mjs";
import { tradeAssets } from "./engine.mjs";
import { disabledChoice, eventChoiceReason } from "./choice-feedback.mjs";
const slots = {
  wrist1: "Left wrist",
  wrist2: "Right wrist",
  finger1: "Left ring",
  finger2: "Right ring",
  head: "Head",
  neck: "Neck",
  torso: "Armor",
};
function details(ctx, x, kind) {
  const d = (kind === "item" ? items : cards)[x.id];
  const gem = kind === "item" && ctx.o.inventory.find((g) => g.uid === x.gem);
  return `<p>${ctx.text(kind === "card" ? cardText(d, ctx.o.stratum) : d.text)}</p>${x.upgrade && d.upgrade ? `<p>Upgrade: ${ctx.text(d.upgrade.text)}</p>` : ""}${kind === "card" ? `<p>${d.element} · ${d.type} · ${d.focus} Focus · ${d.channel} Channel · ${d.limit < 0 ? "∞" : d.limit} activations${x.upgrade ? " · Upgraded" : ""}</p>` : ""}${gem ? `<p class="trade-gem">${items[gem.id].name}: ${ctx.text(items[gem.id].text)}<br>The socketed Gem is given away with this Setting.</p>` : ""}`;
}
function tradeChooser(ctx, index) {
  if (ctx.busy()) return;
  const choice = ctx.o.event.choices[index],
    trade = choice.trade,
    assets = tradeAssets(ctx.o, trade),
    isItem = trade.kind === "item";
  const actions = ctx.actions.filter(
      (a) => a.type === "eventChoice" && a.index === index,
    ),
    key = isItem ? "tradeItem" : "tradeCard";
  const assetMarkup = (x) => {
    const d = (isItem ? items : cards)[x.id],
      eligible = actions.some((a) => a[key] === x.uid),
      gem = isItem && ctx.o.inventory.find((g) => g.uid === x.gem);
    return `<article class="trade-asset ${eligible ? "" : "unavailable"}" data-trade-asset="${x.uid}"><button class="trade-select" data-trade-select="${x.uid}" draggable="${eligible}" ${eligible ? "" : "disabled"} aria-pressed="false"><span class="trade-asset-art">${ctx.img((isItem ? "item-" : "card-") + x.id)}${gem ? `<span class="fitted-gem" data-fitted-gem="${gem.uid}" aria-label="Includes socketed ${ctx.esc(items[gem.id].name)}" title="${ctx.esc(items[gem.id].name)} is given away with this Setting">${ctx.img("item-" + gem.id)}</span>` : ""}</span><b>${d.name}${x.upgrade ? " +" : ""}</b><small>${x.equippedSlot ? slots[x.equippedSlot] : isItem ? "Satchel" : "Grimoire"}</small>${isItem && x.gem ? `<small>Includes ${items[ctx.o.inventory.find((g) => g.uid === x.gem).id].name}</small>` : ""}</button>${x.reason ? `<small>${ctx.esc(x.reason)}</small>` : ""}<details><summary>View details</summary>${details(ctx, x, trade.kind)}</details></article>`;
  };
  const group = (title, list) =>
    list.length
      ? `<section class="trade-group"><h3>${title}</h3><div class="trade-assets">${list.map(assetMarkup).join("")}</div></section>`
      : "";
  const rewards = [
    choice.card ? { id: choice.card, kind: "card" } : null,
    choice.item ? { id: choice.item, kind: "item" } : null,
  ].filter(Boolean);
  ctx.dialog(
    `<div class="trade-heading"><div class="eyebrow">${ctx.esc(ctx.o.event.name)}</div><h2>${ctx.esc(choice.label)}</h2></div><div class="trade-layout"><div class="trade-belongings">${
      isItem
        ? group(
            "Equipped",
            assets.filter((x) => x.equippedSlot),
          ) +
          group(
            "Satchel",
            assets.filter((x) => !x.equippedSlot),
          )
        : group("Grimoire", assets)
    }${assets.length ? "" : "<p>No matching belongings.</p>"}</div><section class="trade-reward" data-trade-drop aria-label="Trade offer drop area"><div class="eyebrow">You receive</div>${rewards.map((x) => `<h3>${(x.kind === "card" ? cards : items)[x.id].name}</h3>${ctx.img(x.kind + "-" + x.id, "trade-reward-art")}<details><summary>View reward</summary>${details(ctx, x, x.kind)}</details>`).join("")}<p class="trade-selection" aria-live="polite">Select or drag a ${ctx.esc(trade.label || trade.kind)} here.</p><button class="primary" data-trade-confirm disabled>Trade selected ${ctx.esc(trade.label || trade.kind)}</button></section></div><div class="trade-footer"><button data-trade-back>← Back to choices</button></div>`,
  );
  ctx.modal.querySelector(".dialog").classList.add("trade-dialog");
  let selected = null,
    dragged = null,
    committed = false;
  const zone = ctx.modal.querySelector("[data-trade-drop]"),
    confirm = ctx.modal.querySelector("[data-trade-confirm]");
  const actionFor = (uid) => actions.find((a) => a[key] === uid);
  const select = (uid) => {
    if (!actionFor(uid)) return;
    selected = uid;
    for (const el of ctx.modal.querySelectorAll("[data-trade-select]"))
      el.setAttribute(
        "aria-pressed",
        String(Number(el.dataset.tradeSelect) === uid),
      );
    const x = assets.find((x) => x.uid === uid),
      d = (isItem ? items : cards)[x.id];
    ctx.modal.querySelector(".trade-selection").textContent =
      `Offer ${d.name}${x.upgrade ? " +" : ""}${isItem && x.gem ? " with " + items[ctx.o.inventory.find((g) => g.uid === x.gem).id].name : ""}${x.equippedSlot ? " · " + slots[x.equippedSlot] : ""}`;
    confirm.disabled = false;
    zone.classList.add("has-offer");
  };
  const commit = (uid) => {
    if (committed || ctx.busy()) return;
    const expected = actionFor(uid),
      current =
        expected && ctx.game.legal().find((a) => a.key === expected.key);
    if (!current) return;
    committed = true;
    ctx.close();
    ctx.act(current);
  };
  for (const el of ctx.modal.querySelectorAll("[data-trade-select]")) {
    const uid = Number(el.dataset.tradeSelect);
    el.onclick = () => select(uid);
    el.ondragstart = (e) => {
      if (!actionFor(uid)) {
        e.preventDefault();
        return;
      }
      dragged = uid;
      select(uid);
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", String(uid));
      zone.classList.add("accepting-offer");
    };
    el.ondragend = () => {
      dragged = null;
      zone.classList.remove("accepting-offer", "drag-over");
    };
  }
  zone.ondragover = (e) => {
    if (dragged != null && actionFor(dragged)) {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      zone.classList.add("drag-over");
    }
  };
  zone.ondragleave = (e) => {
    if (!zone.contains(e.relatedTarget)) zone.classList.remove("drag-over");
  };
  zone.ondrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const uid = dragged;
    dragged = null;
    zone.classList.remove("accepting-offer", "drag-over");
    if (uid != null) commit(uid);
  };
  confirm.onclick = () => commit(selected);
  ctx.modal.querySelector("[data-trade-back]").onclick = () => ctx.close();
}
export function eventTrades(ctx) {
  const choices = ctx.app.querySelector(".scene-copy .choices");
  if (!choices) return;
  choices.innerHTML = ctx.o.event.choices
    .map((c, index) => {
      const legal = ctx.actions.filter(
        (a) => a.type === "eventChoice" && a.index === index,
      );
      if (!legal.length) return disabledChoice(ctx.esc, c.label, eventChoiceReason(ctx.o, c));
      return c.trade
        ? `<button data-event-trade="${index}" ${legal.length ? "" : "disabled"}>${ctx.esc(c.label)}</button>`
        : legal.map((a) => ctx.actionButton(a)).join("");
    })
    .join("");
  for (const el of choices.querySelectorAll("[data-event-trade]"))
    el.onclick = () => tradeChooser(ctx, Number(el.dataset.eventTrade));
  for (const el of choices.querySelectorAll("[data-action]"))
    el.onclick = () => {
      if (!ctx.busy()) ctx.act(el.dataset.action);
    };
}

tutorial-hints.mjs:
import { cards } from "./content.mjs";
import { WeightedPolicy } from "./policy.mjs";
const policy = new WeightedPolicy();
export function tutorialHint(game) {
  const s = game.s,
    b = s.battle;
  if (!s.tutorial || s.tutorial.lesson !== "independent" || s.mode !== "battle")
    return null;
  const legal = game.legal();
  let action;
  if (
    !b.reaction &&
    b.phase === "place" &&
    !legal.some((a) => a.type === "place")
  )
    action = legal.find((a) => a.type === "activatePhase");
  else if (
    !b.reaction &&
    b.phase === "activate" &&
    !legal.some((a) => a.type === "activate")
  )
    action = legal.find((a) => a.type === "endTurn");
  action ||= policy.choose(game.observe(), legal)?.action;
  if (!action) return null;
  const name =
    action.slot == null
      ? "this card"
      : cards[b.grid[action.slot].at(-1)?.id]?.name || "this card";
  let text;
  switch (action.type) {
    case "activatePhase":
      text =
        "Ready to continue? Click the arrow from Placement to Activation to use your Channel.";
      break;
    case "endTurn":
      text =
        "Ready for the enemy? Click the arrow from Activation to Enemy, then choose how to defend.";
      break;
    case "ward":
    case "block":
    case "intercept":
      text = `You could click ${name} to defend against this attack. Choose carefully: the attack cannot move back toward cards on the right.`;
      break;
    case "armor":
      text =
        "You could click the highlighted Armor to protect against this hit, or click the Druid to skip it.";
      break;
    case "bracelet":
      text =
        "You could click the highlighted Bracelet to absorb some of this attack with its remaining Guard.";
      break;
    case "skipEquipment":
      text =
        "Click your Druid to accept the remaining hit. You can choose another available defense instead.";
      break;
    case "place":
      text = `You could place ${cards[b.hand.find((c) => c.uid === action.uid)?.id]?.name || "the highlighted card"} in the highlighted space. Drag it there, or select it and choose the space.`;
      break;
    case "activate":
      text = `You could activate ${name}. ${action.target != null ? "Drag it onto the enemy, or double-click its activation to attack." : "Click its activation button to use the effect."}`;
      break;
    case "recall":
      text = `You could Recall ${name} to free its space. Open its details to see the Recall choice.`;
      break;
    default:
      text = `One available option: ${action.label}.`;
  }
  return { action, text };
}

tutorial-ui.mjs:
import { artPaths } from "./art-paths.mjs";
import { tutorialGuide } from "./tutorial.mjs";
import { tutorialHint } from "./tutorial-hints.mjs";
let context = null,
  layer = null,
  observer = null,
  queued = false,
  idleTimer = null,
  lastActivity = 0,
  lastSteps = null,
  hint = null;
const IDLE_MS = 15000;
function independent() {
  return (
    context?.game.s.mode === "battle" &&
    tutorialGuide(context.game)?.kind === "free"
  );
}
function hideHint() {
  hint = null;
  if (
    independent() &&
    context.game.s.tutorial.independentIntroDismissed &&
    layer
  )
    layer.hidden = true;
  refreshTargets();
}
function armIdle() {
  clearTimeout(idleTimer);
  if (!independent() || !context.game.s.tutorial.independentIntroDismissed)
    return;
  idleTimer = setTimeout(
    checkIdle,
    Math.max(100, IDLE_MS - (performance.now() - lastActivity)),
  );
}
function activity() {
  if (!independent()) return;
  lastActivity = performance.now();
  hideHint();
  armIdle();
}
function checkIdle() {
  if (!independent() || !context.game.s.tutorial.independentIntroDismissed)
    return;
  if (
    context.busy() ||
    !document.querySelector("#modal").hidden ||
    document.hidden ||
    document.querySelector(".presentation-bar")
  ) {
    lastActivity = performance.now();
    armIdle();
    return;
  }
  if (performance.now() - lastActivity < IDLE_MS) {
    armIdle();
    return;
  }
  hint = tutorialHint(context.game);
  if (!hint) return;
  layer.hidden = false;
  layer.innerHTML = `<section class="tutorial-guide tutorial-idle-guide" aria-label="Optional tutorial suggestion" role="status" data-tutorial-hint><div class="tutorial-eyebrow">A GENTLE SUGGESTION</div><p>${escape(hint.text)}</p><small>Your choice · continue playing to dismiss.</small></section>`;
  refreshTargets();
}
const escape = (s) =>
  String(s)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll('"', "&quot;");
function targets(ctx, guide, suggested = null) {
  let selectors = guide.focus ? [guide.focus] : [];
  if (guide.kind === "action")
    for (const a of suggested ? [suggested] : ctx.game.legal()) {
      if (a.type === "place")
        selectors.push(`[data-hand="${a.uid}"], [data-slot="${a.slot}"]`);
      if (a.type === "consume") selectors.push(".consumable-tray");
      if (a.type === "activate") {
        selectors.push(`[data-activate-slot="${a.slot}"]`);
        if(a.target != null) selectors.push(`[data-enemy-uid="${a.target}"]`);
        if(a.destination != null) selectors.push(`[data-slot="${a.destination}"]`);
      }
      if (["ward", "block", "intercept", "recall"].includes(a.type))
        selectors.push(`[data-slot="${a.slot}"]`);
      if (["bracelet", "armor"].includes(a.type))
        selectors.push(`.battle-player [data-item-uid="${a.uid}"]`);
      if (a.type === "skipEquipment")
        selectors.push(".battle-player .player-portrait");
      document.querySelectorAll("[data-action]").forEach((el) => {
        if (el.dataset.action === a.key) mark(el, !!suggested);
      });
    }
  for (const selector of selectors)
    document.querySelectorAll(selector).forEach((el) => {
      if (
        ctx.game.s.mode === "tavern" &&
        el.matches("[data-equip-slot], [data-socket] ") &&
        !el.closest(".tavern-service")
      )
        return;
      mark(el, !!suggested);
    });
}
function mark(el, gentle) {
  el.classList.add("tutorial-target");
  if (gentle) el.classList.add("tutorial-hint-target");
  else if (
    el.matches(
      "button, [data-hand], [data-slot], [data-equip-slot], [data-item-uid], [data-socket], .player-portrait",
    )
  )
    el.classList.add("tutorial-target-control");
}
function refreshTargets() {
  queued = false;
  document
    .querySelectorAll(".tutorial-target")
    .forEach((el) =>
      el.classList.remove(
        "tutorial-target",
        "tutorial-target-control",
        "tutorial-hint-target",
      ),
    );
  if (context && layer) {
    const guide = tutorialGuide(context.game);
    if (guide?.kind === "free") {
      if (hint) targets(context, { kind: "action", focus: "" }, hint.action);
    } else if (guide) targets(context, guide);
  }
}
export function clearTutorialUI() {
  clearTimeout(idleTimer);
  hint = null;
  lastSteps = null;
  context = null;
  if (layer) layer.hidden = true;
  document.body.classList.remove("in-tutorial");
  document
    .querySelectorAll(".tutorial-target")
    .forEach((el) =>
      el.classList.remove(
        "tutorial-target",
        "tutorial-target-control",
        "tutorial-hint-target",
      ),
    );
}
export function paintTutorial(ctx, frame = false) {
  if (!observer) {
    for (const type of [
      "pointerdown",
      "pointermove",
      "keydown",
      "wheel",
      "dragstart",
      "drop",
      "visibilitychange",
    ])
      document.addEventListener(type, activity, {
        capture: true,
        passive: true,
      });
    observer = new MutationObserver(() => {
      if (!queued) {
        queued = true;
        requestAnimationFrame(refreshTargets);
      }
    });
    observer.observe(document.querySelector("#app"), {
      childList: true,
      subtree: true,
    });
    observer.observe(document.querySelector("#modal"), {
      childList: true,
      subtree: true,
    });
  }
  const guide = tutorialGuide(ctx.game);
  if (!guide || ctx.game.s.mode === "result") return clearTutorialUI();
  if (context?.game !== ctx.game || lastSteps !== ctx.game.s.steps || frame) {
    hint = null;
    lastActivity = performance.now();
  }
  lastSteps = ctx.game.s.steps;
  context = ctx;
  document.body.classList.add("in-tutorial");
  if (!layer) {
    layer = document.createElement("aside");
    layer.id = "tutorial-layer";
    document.body.append(layer);
  }
  layer.hidden = !!frame;
  layer.className =
    ctx.game.s.mode === "battle"
      ? "tutorial-battle"
      : ctx.game.s.mode === "field"
        ? "tutorial-road tutorial-field"
        : "tutorial-road";
  if (guide.kind === "free" && ctx.game.s.tutorial.independentIntroDismissed) {
    layer.hidden = true;
    hint = null;
    refreshTargets();
    armIdle();
    return;
  }
  clearTimeout(idleTimer);
  layer.innerHTML = `<section class="tutorial-guide" aria-label="Tutorial guidance" data-tutorial-step="${escape(guide.id)}"><div class="tutorial-eyebrow">${escape(guide.name).toUpperCase()} <span>${guide.index + 1} / ${guide.total}</span></div><div class="tutorial-progress"><i style="width:${(100 * (guide.index + 1)) / guide.total}%"></i></div><h2>${escape(guide.title)}</h2>${guide.id === "welcome" ? `<figure class="tutorial-companion"><img src="${artPaths["card-sapling"]}" alt="Sapling, your first companion"><figcaption>Sapling · Your first companion</figcaption></figure>` : ""}<p>${escape(guide.text)}</p>${guide.kind === "free" ? '<button class="tutorial-next" data-tutorial-independent>Let me try <span aria-hidden="true">→</span></button>' : guide.kind === "note" ? '<button class="tutorial-next" data-tutorial-next>Continue <span aria-hidden="true">→</span></button>' : `<small>${guide.kind === "free" ? "No forced choices · read any keyword for help." : "Follow the highlighted control."}</small>`}</section>`;
  layer
    .querySelector("[data-tutorial-independent]")
    ?.addEventListener("click", async () => {
      if (ctx.busy()) return;
      lastActivity = performance.now();
      await ctx.dismissIndependent();
    });
  layer.querySelector("[data-tutorial-next]")?.addEventListener("click", () => {
    if (ctx.busy()) return;
    ctx.close();
    const a = ctx.game.legal().find((a) => a.type === "tutorialNext");
    if (a) ctx.act(a);
  });
  refreshTargets();
}

