export const TUTORIAL_STEPS = steps;
export function tutorialGuide(g) {
  if (g.s.tutorial?.id === "stratum3") return depthsGuide(g);
  if (g.s.tutorial?.id === "stratum2") return loomGuide(g);
  const t = g.s.tutorial;
  return t && !t.completed
    ? {
        ...steps[t.step],
        index: t.step,
        total: steps.length,
        name: TUTORIAL.name,
      }
    : null;
}
const item = (g, id) => g.s.inventory.find((x) => x.id === id);
function matches(g, a, m) {
  return Object.entries(m).every(([k, v]) => {
    if (k === "card")
      return (
        (
          g.s.battle?.hand.find((c) => c.uid === a.uid) ||
          g.s.deck.find((c) => c.uid === a.uid)
        )?.id === v
      );
    if (k === "itemId")
      return a.type === "buy"
        ? g.s.shop.stock[a.index] === v
        : item(g, v)?.uid === (a.item ?? a.uid);
    if (k === "gemId") return item(g, v)?.uid === a.gem;
    return a[k] === v;
  });
}
export function tutorialActions(g, raw) {
  if (g.s.tutorial?.id === "stratum3") return depthsActions(g, raw);
  if (g.s.tutorial?.id === "stratum2") return loomActions(g, raw);
  const t = g.s.tutorial,
    step = steps[t?.step];
  if (!t) return raw;
  if (g.s.mode === "result")
    return g.s.outcome === "loss" && t.finalStart
      ? [
          {
            type: "tutorialRetry",
            label: "Retry the Warden",
            key: '["tutorialRetry"]',
            effects: { progress: 1 },
            costs: {},
          },
        ]
      : [];
  if (step.kind === "free") return raw;
  if (step.kind === "action")
    return raw
      .filter((a) => matches(g, a, step.match))
      .slice(
        0,
        step.match.type === "place" || step.match.type === "upgrade"
          ? 1
          : undefined,
      );
  const type = step.kind === "ui" ? "tutorialUI" : "tutorialNext";
  return [
    {
      type,
      step: step.id,
      control: step.control,
      label: step.kind === "ui" ? step.title : "Continue lesson",
      key: JSON.stringify([type, { step: step.id }]),
      effects: { progress: 1 },
      costs: {},
    },
  ];
}
function spawn(g, type, x, y, extra = {}) {
  g.s.field.entities.push({
    uid: g.uid(),
    type,
    x,
    y,
    born: g.s.field.round,
    restless: 0,
    ...extra,
  });
}
function enter(g) {
  const t = g.s.tutorial,
    step = steps[t.step],
    f = g.s.field;
  if (!step) throw Error("Unknown tutorial step");
  t.lesson = step.id;
  if (
    t.legacySupplies &&
    step.match?.type === "consume" &&
    !g.s.inventory.some((x) => x.id === step.match.itemId)
  )
    g.addItem(step.match.itemId);
  if (step.id === "independent")
    t.finalStart = {
      battle: structuredClone(g.s.battle),
      hp: g.s.hp,
      inventory: structuredClone(g.s.inventory),
    };
  switch (step.setup) {
    case "supply-route":
      if (t.relocateSupplies) {
        const ids = ["healingSap", "insightDew", "focusDraught"];
        f.entities = f.entities.filter((e) => !e.fieldSupply);
        for (const id of ids) {
          const i = g.s.inventory.findIndex((x) => x.id === id);
          if (i >= 0) g.s.inventory.splice(i, 1);
        }
        delete t.relocateSupplies;
      }
      for (const [id, x, y] of [
        ["healingSap", 10, 0],
        ["insightDew", 9, 0],
        ["focusDraught", 8, 0],
      ])
        if (!f.entities.some((e) => e.fieldSupply && e.item === id))
          spawn(g, "Item", x, y, { item: id, fieldSupply: true });
      break;
    case "gold":
      spawn(g, "Gold", 6, 5, { value: 200 });
      break;
    case "ring":
      spawn(g, "Item", 7, 5, { item: "ring" });
      break;
    case "mote":
      spawn(g, "Mote", 8, 5, { enemy: "tutorialMosswing", count: 1 });
      break;
    case "pursuit":
      spawn(g, "Item", 10, 2, { item: "sapphire" });
      spawn(g, "Mote", 8, 4, { enemy: "tutorialRootling", count: 1 });
      f.moves = 2;
      break;
    case "gem-road":
      f.moves = 2;
      break;
    case "ember":
      spawn(g, "Mote", 7, 1, { enemy: "tutorialEmber", count: 1 });
      break;
    case "tavern":
      spawn(g, "Tavern", 6, 1);
      break;
    case "final":
      spawn(g, "Eidolon", 5, 1, { enemy: "tutorialWarden", count: 1 });
      break;
  }
}
export function startTutorial(g) {
  const s = g.s;
  s.tutorial = {
    ...TUTORIAL,
    step: 0,
    lesson: "welcome",
    fight: 0,
    completed: false,
  };
  s.mode = "field";
  s.archon = "hart";
  s.revealedArchon = null;
  s.gold = 0;
  s.inventory = s.inventory.filter((x) => x.id === "bronze");
  for (const k of Object.keys(s.equipment))
    if (k !== "wrist2") s.equipment[k] = null;
  s.deck = [
    ...Array(4).fill("shield"),
    ...Array(4).fill("blast"),
    "sapling",
    "clear",
  ].map((id) => g.newCard(id));
  Object.assign(s.field, {
    round: 1,
    spawned: 0,
    queue: [],
    entities: [],
    x: 5,
    y: 5,
    moves: 2,
    stage: "player",
  });
  s.stats.itemsGained = ["Bronze Bracelet"];
  enter(g);
  return g;
}
export function tutorialAfter(g, a) {
  if (g.s.tutorial?.id === "stratum3") return depthsAfter(g, a);
  if (g.s.tutorial?.id === "stratum2") return loomAfter(g, a);
  const t = g.s.tutorial;
  if (!t) return;
  if (a.type === "tutorialRetry") {
    const saved = t.finalStart;
    g.s.battle = structuredClone(saved.battle);
    g.s.hp = saved.hp;
    if (saved.inventory) g.s.inventory = structuredClone(saved.inventory);
    g.s.status = { burn: 0, poison: 0, corrode: 0 };
    g.s.mode = "battle";
    delete g.s.outcome;
    delete g.s.death;
    delete g.s.cause;
    g.s.stats.encounters.push({
      round: g.s.field.round,
      enemies: [enemies.tutorialWarden.name],
      outcome: "in progress",
      hpStart: g.s.hp,
    });
    t.completed = false;
    t.step = steps.length - 1;
    t.lesson = "independent";
    t.retries = (t.retries || 0) + 1;
    return;
  }
  if (steps[t.step].kind === "free" || t.completed) return;
  t.step++;
  if (
    a.type === "consume" &&
    t.legacySkipSupplyRoute &&
    !g.s.inventory.some((x) => x.id === "sapphire")
  ) {
    t.step = steps.findIndex((x) => x.id === "gem-road");
    delete t.legacySkipSupplyRoute;
  }
  enter(g);
}
export function tutorialBattle(g, entities) {
  if (["stratum2", "stratum3"].includes(g.s.tutorial?.id)) return;
  if (!g.s.tutorial) return;
  g.s.tutorial.fight =
    {
      tutorialMosswing: 1,
      tutorialRootling: 2,
      tutorialEmber: 3,
      tutorialWarden: 4,
    }[entities[0].enemy] || 0;
}
export function tutorialBattleReady(g) {
  if (["stratum2", "stratum3"].includes(g.s.tutorial?.id)) return;
  const t = g.s.tutorial;
  if (t?.fight === 4)
    t.finalStart = { battle: structuredClone(g.s.battle), hp: g.s.hp };
}
export function tutorialDrawIndex(g, n) {
  if (["stratum2", "stratum3"].includes(g.s.tutorial?.id)) return 0;
  const b = g.s.battle,
    t = g.s.tutorial;
  const plans = {
    1: {
      1: ["shield", "shield", "shield", "shield"],
      2: ["blast", "blast", "blast", "blast"],
      3: ["sapling", "clear", "blast", "blast"],
    },
    2: {
      1: ["ward", "blast", "blast", "clear"],
      2: ["sapling", "blast", "blast", "shield"],
      3: ["shield", "shield", "shield", "blast"],
      4: ["blast"],
    },
    3: { 1: ["water", "shield", "shield", "shield"], 2: ["blast"] },
    4: { 1: ["shield"] },
  };
  const id = plans[t.fight]?.[b.turn]?.[n];
  const i = b.deck.findIndex((c) => c.id === id);
  return i < 0 ? 0 : i;
}
export function tutorialReward(g) {
  if (g.s.tutorial?.id === "stratum3") {
    g.s.tutorial.completed = true;
    g.finish(true, "The Listening Hollow complete");
    return true;
  }
  if (g.s.tutorial?.id === "stratum2") {
    g.s.tutorial.completed = true;
    g.finish(true, "The Mending Ground complete");
    return true;
  }
  const t = g.s.tutorial;
  if (!t) return false;
  if (t.fight === 4) {
    t.completed = true;
    g.finish(true, "The First Clearing complete");
    return true;
  }
  g.s.reward = {
    cards: t.fight === 1 ? ["ward"] : t.fight === 2 ? ["water"] : null,
    gem: false,
    setting: false,
    boss: false,
  };
  return false;
}
export function tutorialTavern(g) {
  if (["stratum2", "stratum3"].includes(g.s.tutorial?.id)) return;
  if (!g.s.tutorial) return;
  g.s.shop = {
    stock: ["crown", "starFlask", "channelDraught"],
    healer: true,
    healerPrice: 35,
    hexPrice: { kind: "gold", gold: 35, hp: 0 },
    healUsed: false,
    removeUsed: false,
  };
}

export function normalizeTutorial(s) {
  if (s.tutorial?.id === "stratum3") return normalizeDepthsTutorial(s);
  if (["stratum2", "stratum3"].includes(s.tutorial?.id)) return;
  const t = s.tutorial;
  if (!t) return;
  if (t.version < 9) {
    t.legacySupplies = true;
    if (t.lesson === "consume-healing") t.legacySkipSupplyRoute = true;
    if (
      s.mode === "tavern" &&
      s.shop &&
      !s.shop.stock.includes("channelDraught")
    )
      s.shop.stock.push("channelDraught");
  }
  if (t.version < 10) {
    const route = [
      "consumables",
      "healing-road",
      "healing-pickup",
      "consume-healing",
      "insight-road",
      "insight-pickup",
      "focus-road",
      "focus-pickup",
      "supplies-return-one",
      "supplies-return-two",
    ];
    const hasGem = s.inventory.some((x) => x.id === "sapphire");
    if (route.includes(t.lesson) && !hasGem) {
      t.lesson = "gem-road";
      s.mode = "field";
      s.field.x = 10;
      s.field.y = 3;
      s.field.moves = 2;
      delete s.itemSource;
      delete s.itemChoices;
      t.relocateSupplies = true;
    } else if (route.includes(t.lesson) && hasGem) {
      t.lesson = "gem-save";
      s.mode = "field";
      s.field.x = 10;
      s.field.y = 2;
      s.field.moves = 2;
      t.relocateSupplies = true;
    }
    if (t.fight < 3) {
      s.field.entities = s.field.entities.filter((e) => !e.fieldSupply);
      t.relocateSupplies = true;
    }
    if (["curses", "ember-move"].includes(t.lesson)) {
      s.field.x = 8;
      s.field.y = 0;
      s.field.moves = 2;
    }
    if (t.fight === 3 && s.mode === "battle") {
      s.field.x = 7;
      s.field.y = 1;
      const e = s.battle.enemies.find((e) => e.id === "tutorialEmber");
      if (e) {
        e.hp += Math.max(0, 29 - e.maxHp);
        e.maxHp = Math.max(29, e.maxHp);
        e.rotation = structuredClone(enemies.tutorialEmber.rotation);
      }
    }
    if (["element-back", "cycle", "tavern-move"].includes(t.lesson)) {
      s.field.x = 7;
      s.field.y = 1;
    }
    if (
      s.mode === "tavern" ||
      ["final-intro", "final-move"].includes(t.lesson)
    ) {
      s.field.x = 6;
      s.field.y = 1;
    }
    for (const e of s.field.entities) {
      if (e.enemy === "tutorialEmber") {
        e.x = 7;
        e.y = 1;
      }
      if (e.type === "Tavern") {
        e.x = 6;
        e.y = 1;
      }
      if (e.enemy === "tutorialWarden") {
        e.x = 5;
        e.y = 1;
      }
    }
    if (
      ["warden-shield", "consume-channel", "consume-channel-use"].includes(
        t.lesson,
      )
    ) {
      t.lesson = "independent";
      t.finalStart = {
        battle: structuredClone(s.battle),
        hp: s.hp,
        inventory: structuredClone(s.inventory),
      };
    }
  }
  const old = t.version < 3;
  if (old && t.lesson === "gem-step") t.lesson = "gem-road";
  const index = steps.findIndex((step) => step.id === t.lesson);
  if (index < 0) throw Error("Unknown saved tutorial lesson: " + t.lesson);
  t.step = index;
  if (old) {
    if (["pursuit", "pursuit-move"].includes(t.lesson)) {
      s.field.moves = 2;
      const rootling = s.field.entities.find(
        (e) => e.enemy === "tutorialRootling",
      );
      if (rootling) {
        rootling.x = 8;
        rootling.y = 4;
      }
    }
    const caught = steps.findIndex((step) => step.id === "caught");
    const gemRoad = steps.findIndex((step) => step.id === "gem-road");
    if (index >= caught && index <= gemRoad) {
      s.field.x = 10;
      s.field.y = 3;
      for (const e of s.field.entities.filter(
        (e) => e.enemy === "tutorialRootling",
      )) {
        e.x = 10;
        e.y = 3;
      }
    }
  }
  if (
    t.version < 7 &&
    s.mode === "battle" &&
    t.fight === 2 &&
    !s.battle.enemyFirst
  ) {
    t.restartRootling = true;
    t.lesson = "caught";
    t.step = steps.findIndex((step) => step.id === "caught");
  }
  t.version = TUTORIAL.version;
}

