      );
    }
    audio.emit("decision");
    selectedHand = null;
    selectedSlot = null;
    await storage.record(
      runRecord(game, runId, "decision", {
        action,
        controller,
        elapsedMs: Date.now() - started,
      }),
    );
    await persist();
    await playFrames(
      before,
      game.presentation || [],
      game.observe(),
      render,
      () => settings.fast,
    );
    render();
    if (
      action.type === "enterLoom" &&
      !data.tutorialStats?.stratum2?.firstCompletedAt
    )
      startLoom = true;
    if (action.type === "enterDepths" && !data.tutorialStats?.stratum3?.firstCompletedAt)
      startDepths = true;
  } catch (e) {
    toast(e.message);
    console.error(e);
  } finally {
    busy = false;
  }
  if (startLoom) await ui("loomTutorial");
  if (startDepths) await ui("depthsTutorial");
