async function stepBot() {
  if (
    !game ||
    game.s.mode === "result" ||
    (game.s.tutorial && tutorialGuide(game)?.kind !== "free")
  ) {
    auto = false;
    return;
  }
  const d = policy.choose(game.observe(), game.legal());
  if (!d) {
    auto = false;
    toast("No legal choice available.");
    return;
  }
  reason = d.reason;
  await act(d.action, {
    kind: "ai",
    policy: policy.id,
    weights: policy.weights,
    reason: d.reason,
  });
}
